"use strict";exports.id=7350,exports.ids=[7350],exports.modules={27350:(a,b,c)=>{c.d(b,{U:()=>o});let d=(a,b)=>b.map((b,c)=>({src:`/images/ms-office/teams/module-1/${a}/slide-${String(c+1).padStart(2,"0")}.jpg`,alt:b})),e=[{slug:"teams-at-work",title:"Teams at Work: What It Is and How It Is Organized",description:"Learn what Microsoft Teams is for, how chats, teams, channels, and meetings fit together, which version of Teams you will use at work, and the patient-information rule that comes with it.",objectives:["Explain what Teams is for and name its main parts: Activity, Chat, teams and channels, Calendar, Calls, and OneDrive","Tell the difference between a chat, a team, a channel, and a meeting","Describe how a work or school account differs from Microsoft Teams (free), and why classic Teams no longer appears","Apply Lakeside's rule for patient information in Teams"],duration:"15 min",videoUrl:"https://www.youtube.com/embed/vaeFzrIc9HU",slides:d("teams-at-work",["Microsoft Teams: one place for chat, meetings, calls, and shared files","Chat, team, channel, meeting: four ways to talk at work","Where a conversation belongs: a decision guide","Work or school account versus Microsoft Teams (free)","One Teams app: classic Teams is retired","The patient information rule for Teams at Lakeside","Quick check: chat or channel?"]),sections:[{heading:"Why the office runs on Teams",blocks:[{type:"scenario",role:"You are a new front office assistant at Lakeside Medical Associates.",text:"On your first day, Maria Santos, the office manager, tells you that nobody at Lakeside sends quick questions by email anymore. Schedule changes go in the Scheduling channel, coverage questions come by chat, the morning huddle is a Teams meeting, and the intake packet lives in the Front Office team. Within an hour you have a chat from Maria, an @mention in a channel, and a meeting invitation, and you are not sure which one to answer first or where.",task:"Learn what each part of Teams is for, so every message you send lands in the right place."},{type:"paragraph",text:"Microsoft Teams is the app many workplaces use to talk and work together. It brings chat, meetings, phone-style calls, and shared files into one window. The big idea is that conversations live next to the work they are about. Instead of an email thread that only some people can see, the front office has one Scheduling channel that everyone on the team can read, search, and reply to."},{type:"key-terms",terms:[{term:"Chat",definition:"A private conversation with one person or a small group. Only the people in the chat can see it."},{term:"Team",definition:"A group of people who work together, such as the Front Office team. A team holds channels."},{term:"Channel",definition:"A topic area inside a team, such as Scheduling or Billing Questions. Everyone on the team can read a standard channel."},{term:"Post",definition:"A message in a channel. Replies stay together under the post."},{term:"Meeting",definition:"A scheduled or instant video or audio call, with its own meeting chat."},{term:"@mention",definition:"Typing @ and a name so that person gets a notification."},{term:"Activity",definition:"Your feed of notifications: @mentions, replies, reactions, and missed calls."}]}]},{heading:"Chat, team, channel, or meeting?",blocks:[{type:"paragraph",text:"Most mistakes new Teams users make are about place, not buttons: a question for one person posted where 40 people see it, or a schedule change sent in a private chat that the rest of the team never sees. Before you type, ask who needs to see this and whether they will need to find it again later."},{type:"table",caption:"Choose the right place for the message",columns:["Use","When","Lakeside example"],rows:[["One-on-one chat","Something only one person needs","Asking Maria if you can leave 10 minutes early"],["Group chat","A short-term topic for a few people","Three people coordinating a Room 3 supply restock today"],["Channel post","Team information others should see and find later","Dr. Shah's Friday schedule change in Scheduling"],["Meeting","Something that needs a real-time conversation","The 9:45 Front Office Huddle"]]},{type:"drag-drop",mode:"sort",title:"Where does it belong?",prompt:"Drag each message to the place it belongs in Teams.",buckets:[{id:"chat",label:"Chat (one person or a small group)"},{id:"channel",label:"Channel post (the whole team)"},{id:"meeting",label:"Meeting"}],items:[{id:"a",text:"Asking Maria privately whether you can swap Friday shifts",bucket:"chat"},{id:"b",text:"Telling the front office that the copay reference sheet was updated",bucket:"channel"},{id:"c",text:"A 15-minute talk with the whole front desk about a new check-in process",bucket:"meeting"},{id:"d",text:"Letting everyone on the team know Dr. Shah is out Friday afternoon",bucket:"channel"},{id:"e",text:"Asking Tasha if she has a minute to help with the label printer",bucket:"chat"},{id:"f",text:"A video call with IT to walk through a new phone system",bucket:"meeting"}],explanation:"Private and short-term goes in a chat. Information the team needs to see and find later goes in a channel. Something that needs everyone talking at the same time is a meeting."}]},{heading:"Which Teams you will use",blocks:[{type:"paragraph",text:"At work you sign in to Teams with the work or school account your employer gives you, such as amorgan@lakesidemedical.example. Your organization manages that account: it decides which teams exist, what apps are available, and settings such as how long chat messages are kept. You can use Teams as a desktop app, in a web browser, or on a phone, and your chats, teams, and meetings are the same on each one."},{type:"table",caption:"Two kinds of Teams accounts",columns:["","Work or school account","Microsoft Teams (free)"],rows:[["Who manages it","Your employer or school","You (personal Microsoft account)"],["Made for","Teams, channels, meetings, and files at work","Friends, family, and community groups"],["Group meetings","Set by your organization's plan","Up to 60 minutes, up to 100 participants"],["Cloud storage","Work OneDrive and the team's SharePoint site","5 GB per user"]]},{type:"callout",variant:"version",text:"There is now one Teams app. Microsoft ended classic Teams: after July 1, 2025, the classic client no longer works, and people use the new Teams app or Teams on the web instead. If a guide tells you to download or switch to classic Teams, it is out of date. This course shows current Teams."}]},{heading:"Patient information in Teams",blocks:[{type:"callout",variant:"warning",text:"Lakeside's rule: patient details (names with health information, dates of birth, diagnoses, insurance numbers) belong in the EHR, not in Teams channels or group chats. In Teams, refer to a patient the way the office allows (for example, by appointment time and room) and share only what the person you are messaging needs to do their job. Never post patient information in a channel, in a team with guests from outside Lakeside, or in a chat with someone who does not need it."},{type:"worked-example",title:"Answering Maria's @mention the right way",task:"Maria @mentioned you in the Scheduling channel: can you cover the front desk Friday from 1:00 to 5:00 PM?",steps:[{move:"Open Activity and select Maria's mention.",why:"Activity takes you straight to the exact post. You do not have to remember which team or channel it was in."},{move:"Select Reply under her post, not Start a post.",why:"A reply keeps the answer attached to the question. A new post would start a separate conversation that others might miss."},{move:"Answer clearly: “Yes, I'm covering the front desk Friday from 1:00 to 5:00 PM.”",why:"Restating the day and times means nobody has to scroll up to know what you agreed to."}],result:"Maria and the whole team can see the coverage is confirmed, right under the question.",takeaway:"Answer where you were asked. Reply in the thread for channel posts, and in the same chat for chat messages."}]},{heading:"Knowledge check",blocks:[{type:"knowledge-check",question:"Dr. Shah will be out Friday afternoon, and the whole front office needs to reschedule her patients. Where should Maria share this?",options:["In a one-on-one chat with each front desk worker","As a post in the Front Office team's Scheduling channel","In her Teams status message","In a meeting chat for an old meeting"],correctIndex:1,explanation:"A channel post reaches the whole team at once, keeps the replies together, and stays searchable for anyone who joins later.",optionRationales:["Separate chats repeat the same message many times and nobody sees what the others did.","Correct. Team information belongs in the team's channel, where everyone sees the same message and the replies.","A status message is a short note about your own availability, not a place for team news.","An old meeting chat only reaches the people who were invited to that meeting."]},{type:"knowledge-check",question:"Which statement about versions of Teams is true today?",options:["You must install classic Teams to join work meetings","Classic Teams stopped working after July 1, 2025; people use the new Teams app or Teams on the web","Microsoft Teams (free) has no limit on meeting length","A work account and a free account are managed the same way"],correctIndex:1,explanation:"Microsoft's end of availability for classic Teams was July 1, 2025. The new Teams app and Teams on the web are what people use now.",optionRationales:["Classic Teams no longer works; the new Teams app replaced it.","Correct.","Teams (free) group meetings are limited to 60 minutes.","Your employer manages a work account. You manage a free account yourself."]}]}],challenge:[{type:"paragraph",text:"Your school computer does not let you sign in to Teams, so you will complete this orientation in the Challenge Lab below, a working copy of Lakeside's Teams. Work through the checklist in order:"},{type:"list",ordered:!0,items:["Open Activity and open the newest notification.","In the Front Office team's General channel, reply to Maria's welcome post: “Hi everyone, I'm Alex, the new front office assistant.”","Open your chat with Maria Santos and send: “Thanks, Maria. I'll see you at the huddle.”","Accept the invitation “New Staff Orientation.”","Open “New Hire Checklist.docx” from OneDrive.","In a Word document or on paper, write two or three sentences explaining when you would use a chat and when you would use a channel post. Use one Lakeside example for each."]},{type:"callout",variant:"success",text:"Deliverable: Submit your Challenge Lab results page (print it or save it as a PDF) and your chat-versus-channel sentences to your instructor or course folder."}]},{slug:"find-your-way-around",title:"Find Your Way Around Teams",description:"Learn the parts of the Teams window: the app bar, the Chat list with Favorites, Chats, and Teams and channels, Search, Settings, and the two ways to arrange chats and channels.",objectives:["Name the parts of the Teams window and what each one is for","Find any chat, channel, or person with Search (Ctrl+E)","Pin chats and channels so they appear in Favorites","Switch between the Combined and Separate views and explain the difference"],duration:"15 min",videoUrl:"https://www.youtube.com/embed/sDb8Xu47xBM",slides:d("find-your-way-around",["A tour of the Teams window","The app bar: Activity, Chat, Calendar, Calls, OneDrive, and Apps","The Chat list: Favorites, Chats, and Teams and channels","Search finds people, chats, and channels (Ctrl+E)","Combined or Separate view: two ways to arrange chats and channels","Keyboard shortcuts worth learning first"]),sections:[{heading:"The Teams window",blocks:[{type:"scenario",role:"You are the front office assistant at Lakeside Medical Associates.",text:"Maria asks you to check the Safety and Compliance channel, pull up your chat with Kevin in billing, and open the provider schedule, all before the 9:45 huddle. Every one of those is two or three clicks away, if you know where they live.",task:"Learn the layout of Teams so you can get anywhere in a couple of clicks."},{type:"paragraph",text:"The Teams window has the same layout everywhere you go. The app bar runs down the left side. Next to it is a list (your chats, your calendar's controls, your files), and the large area on the right shows whatever you picked from the list. Across the top are Search, Settings and more (…), and your profile picture, where you set your status."},{type:"table",caption:"The app bar on the left",columns:["Button","What it opens"],rows:[["Activity","Notifications: @mentions, replies to your posts, reactions, and missed calls"],["Chat","Your chats, and in the default Combined view, your teams and channels too"],["Calendar","Your meetings and events, with New event and Meet now"],["Calls","Calling people by name, plus your call history"],["OneDrive","Your work files: My files, files shared with you, and the Recycle bin"],["Apps","Apps you can add, such as Planner and Approvals"]]},{type:"image",src:"/images/ms-office/teams/module-1/find-your-way-around/infographic.png",alt:"Teams window quick reference: the app bar, the Chat list sections, Search, Settings and more, and the profile picture, with the first keyboard shortcuts to learn",caption:"Teams window quick reference"}]},{heading:"The Chat list: Favorites, Chats, and Teams and channels",blocks:[{type:"paragraph",text:"In current Teams, chats and channels live together. Select Chat on the app bar and you see sections: Favorites (anything you pinned), Chats (your one-on-one and group chats, newest first), and Teams and channels (each team you belong to, with its channels underneath). Names in bold have something new. The Filter button at the top narrows the list to Unread, Chats, Channels, or Meetings."},{type:"paragraph",text:"To keep what you use most at the top, pin it. Point to a chat or channel, select More options (…), and choose Pin. Pinned items move into Favorites. Pin the two or three places you check all day (for Alex, that is the Scheduling channel and the chat with Maria), not everything."},{type:"callout",variant:"info",text:"Prefer the older arrangement? Teams calls the default layout Combined. You can switch to Separate, which gives teams and channels their own Teams button on the app bar again. At the top of the chat list, select More list options (…) › Customize view, or go to Settings and more (…) › Settings › Chats and channels. Both views show the same chats and channels."},{type:"drag-drop",mode:"match",title:"Match the part of Teams to its job",prompt:"Drag each description onto the part of Teams it describes.",items:[{id:"a",text:"Activity",match:"Shows your @mentions, replies, and reactions"},{id:"b",text:"Favorites",match:"Holds the chats and channels you pinned"},{id:"c",text:"Search (Ctrl+E)",match:"Finds a person, chat, or channel by name"},{id:"d",text:"Settings and more (…)",match:"Opens Settings, such as notifications and devices"},{id:"e",text:"Your profile picture",match:"Changes your status and status message"}],explanation:"Activity tells you what needs you, Favorites keeps your daily places close, Search gets you anywhere, Settings and more holds your preferences, and your picture controls how others see your availability."}]},{heading:"Search and shortcuts",blocks:[{type:"paragraph",text:"The Search box at the top of Teams is the fastest way anywhere. Press Ctrl+E (or select the box), type part of a name, and pick the person, chat, or channel from the list. Choosing a person opens your chat with them. Search also finds messages, which helps when someone asks, “Where did Maria post the holiday schedule?”"},{type:"table",caption:"Keyboard shortcuts to learn first (Windows desktop app)",columns:["Press","To"],rows:[["Ctrl+E","Go to Search"],["Ctrl+N","Start a new chat"],["Ctrl+. (period)","See all keyboard shortcuts"],["Ctrl+, (comma)","Open Settings"],["Ctrl+1, Ctrl+2, …","Open the app in that position on the app bar"]]},{type:"worked-example",title:"Setting up Favorites for a front desk day",task:"Make the Scheduling channel and the chat with Maria one click away.",steps:[{move:"In Chat, under Teams and channels › Front Office, point to Scheduling and select More options (…) › Pin.",why:"Scheduling is where coverage and schedule changes are posted. Pinning puts it in Favorites at the top of the list."},{move:"Point to Maria Santos in Chats and select More options (…) › Pin.",why:"Maria is the person you hear from most. A pinned chat never scrolls out of sight."},{move:"Mute the Front Desk Lunch Orders group chat (More options › Mute).",why:"Muting stops the notifications but keeps the chat in your list. You can still read it at lunchtime."}],result:"The two places you check all day sit in Favorites, and the lunch chat stops interrupting you.",takeaway:"Pin what you use daily, mute what you only need sometimes, and search for everything else."}]},{heading:"Knowledge check",blocks:[{type:"knowledge-check",question:"In current Teams with the default Combined view, where do you find the channels of the Front Office team?",options:["Under a Teams button on the app bar","In Chat, in the Teams and channels section","In OneDrive","In Calendar"],correctIndex:1,explanation:"In the Combined view, teams and channels are listed in Chat under Teams and channels. The separate Teams button appears only if you switch to the Separate view.",optionRationales:["That is the Separate view. In the default Combined view there is no Teams button.","Correct.","OneDrive shows your files, not channels.","Calendar shows meetings and events."]},{type:"knowledge-check",question:"Which keyboard shortcut moves you to the Search box?",options:["Ctrl+N","Ctrl+E","Ctrl+Shift+M","Ctrl+,"],correctIndex:1,explanation:"Ctrl+E goes to Search. Ctrl+N starts a new chat, Ctrl+Shift+M mutes you in a meeting, and Ctrl+, opens Settings.",optionRationales:["Ctrl+N starts a new chat.","Correct.","Ctrl+Shift+M toggles your microphone in a meeting.","Ctrl+, opens Settings."]}]}],challenge:[{type:"paragraph",text:"Set up your Teams workspace in the Challenge Lab below, a working copy of Lakeside's Teams:"},{type:"list",ordered:!0,items:["Pin the Scheduling channel.","Pin your chat with Maria Santos.","Mute the group chat “Front Desk Lunch Orders.”","Use Search to open the Billing Questions channel.","Switch to the Separate view.","Switch back to the Combined view."]},{type:"callout",variant:"success",text:"Deliverable: Submit your Challenge Lab results page (print it or save it as a PDF) to your instructor or course folder."}]},{slug:"status-and-presence",title:"Status, Presence, and Status Messages",description:"Learn what each Teams status means, when Teams changes your status for you, and how to set a status message that tells coworkers when you will answer and who to contact instead.",objectives:["Explain what Available, Busy, Do not disturb, Be right back, Appear away, and Appear offline tell other people","Describe when Teams changes your status automatically","Set, reset, and time a status, and set a status message that clears itself","Write a status message that is useful to coworkers and does not include patient information"],duration:"12 min",slides:d("status-and-presence",["Your status tells coworkers when to expect an answer","The six statuses you can choose","When Teams changes your status for you","Status messages: what to say and when to clear it","Change, time, and reset your status","Quick check: which status fits?"]),sections:[{heading:"Why your status matters at the front desk",blocks:[{type:"scenario",role:"You are covering the check-in window at Lakeside Medical Associates.",text:"Twice this morning, Kevin messaged you a billing question while you were checking in a line of patients, then walked over to ask why you had not answered. Your Teams status said Available the whole time, so as far as Kevin could tell, you were ignoring him.",task:"Use your status and a status message so coworkers know when you can answer and who to ask in the meantime."},{type:"paragraph",text:"Your status (Teams also calls it presence) is the small colored dot on your picture. Everyone in your organization sees it next to your name in chats, channels, and meetings. It answers one question for them: can I expect a reply from this person right now? A status message adds a sentence of detail, such as when you will be back and who to contact instead."},{type:"table",caption:"Statuses you can choose",columns:["Status","What it tells people","Use it when"],rows:[["Available","You can respond","You are at your desk and free"],["Busy","You are working on something; messages still notify you","You are checking in patients but can glance at messages"],["Do not disturb","Only priority contacts get through; notifications are silenced","Training, a meeting you are leading, or focused work"],["Be right back","You stepped away briefly","A short break"],["Appear away","You are away from your desk","Lunch or a longer break"],["Appear offline","You look offline, but you can still receive messages","Rarely; use Do not disturb instead when you need quiet"]]}]},{heading:"Automatic status changes",blocks:[{type:"paragraph",text:"Teams also sets your status for you. During a meeting, Busy shows as In a meeting, and during a call as In a call, unless you chose Do not disturb. When you share your screen, Teams turns on Do not disturb so pop-up messages do not appear for everyone to see. If your computer locks or goes to sleep, Available changes to Away. When you pick a status yourself, it stays until you change it, until the duration you chose runs out, or until you select Reset status, which hands control back to Teams."},{type:"list",ordered:!0,items:["Select your picture at the top right of Teams.","Select your current status and pick a new one from the list.","To set it for a limited time, choose Duration, pick the status, choose when to reset it, and select Done.","To go back to automatic, select Reset status."]},{type:"drag-drop",mode:"match",title:"Pick the right status",prompt:"Drag the status that fits each situation.",items:[{id:"a",text:"Annual privacy training for one hour",match:"Do not disturb"},{id:"b",text:"Stepping away for five minutes to restock clipboards",match:"Be right back"},{id:"c",text:"Checking in a line of patients, still glancing at messages",match:"Busy"},{id:"d",text:"Back at your desk with nothing urgent",match:"Available"},{id:"e",text:"Out to lunch for an hour",match:"Appear away"}],explanation:"Choose the status that sets the right expectation: Busy when you are working but reachable, Do not disturb when you should not be interrupted, and Be right back or Appear away when you are not at your desk."}]},{heading:"Status messages that help",blocks:[{type:"paragraph",text:"A status message appears when people point to your name and, if you choose, when they start typing a message to you. Select your picture › Set status message, type the message, check Show when people message me, pick when it should clear under Clear status message after, and select Done. Choosing a clear time matters: a message that says “At lunch” is confusing at 4:00 PM."},{type:"worked-example",title:"Writing a status message for a check-in shift",task:"Let coworkers know you are at the check-in window and who to call for something urgent.",steps:[{move:"Set your status to Busy.",why:"You can still glance at messages, but people should not expect an instant reply."},{move:"Type: “Covering the check-in window until 1:00 PM. For urgent schedule changes, call ext. 210.”",why:"It says what you are doing, when it ends, and gives a backup for anything urgent. That is everything someone needs to decide whether to wait."},{move:"Choose Today under Clear status message after, and select Done.",why:"The message disappears on its own, so you do not leave an out-of-date note for tomorrow."}],result:"Kevin sees the note the moment he starts typing and calls ext. 210 for the urgent question instead of walking over.",takeaway:"A good status message answers three questions: what are you doing, until when, and who can help in the meantime."},{type:"callout",variant:"warning",text:"Everyone in the organization can see your status message. Never include patient details, such as “With Mrs. ___ about her test results.” Describe your task, not the patient."}]},{heading:"Knowledge check",blocks:[{type:"knowledge-check",question:"You picked Do not disturb for training and forgot to change it. Two hours later coworkers think you are still unavailable. What is the best way to hand your status back to Teams?",options:["Restart your computer","Select your picture › your status › Reset status","Set a status message","Choose Appear offline"],correctIndex:1,explanation:"Reset status returns control to Teams, which sets your status automatically from your activity and calendar. Next time, choose Duration so it resets on its own.",optionRationales:["Restarting does not change a status you chose yourself.","Correct.","A status message adds text; it does not change the status.","Appear offline would make the problem worse."]},{type:"knowledge-check",question:"Which status message is the most useful and appropriate?",options:["“Busy.”","“With a patient about her lab results until 2.”","“At the check-in window until 1:00 PM. For urgent questions, call ext. 210.”","“Don't message me.”"],correctIndex:2,explanation:"It tells people what you are doing, until when, and who to contact instead, without any patient information.",optionRationales:["Your status already says Busy. The message should add detail.","It includes patient health information that does not belong in a status message.","Correct.","It is unprofessional and gives no alternative."]}]}],challenge:[{type:"paragraph",text:"You are stepping away for lunch and Omar Haddad is covering check-in. Complete these steps in the Challenge Lab below:"},{type:"list",ordered:!0,items:["Set your status to Be right back.","Set the status message “At lunch until 1:00 PM. Omar Haddad is covering check-in.” Show it when people message you, and clear it after 1 hour.","When you are back, set your status to Available.","Clear your status message."]},{type:"callout",variant:"success",text:"Deliverable: Submit your Challenge Lab results page (print it or save it as a PDF) to your instructor or course folder."}]},{slug:"notifications-and-settings",title:"Notifications, Activity, and Settings",description:"Control which Teams notifications reach you and how, mute busy chats, set channel notifications, and set up and test your headset before your first call.",objectives:["Use the Activity feed to catch up on what needs you","Choose where each kind of notification appears in Settings › Notifications and activity","Mute a chat and set channel notifications for the channels you follow","Choose a speaker and microphone in Settings › Devices and make a test call"],duration:"15 min",slides:d("notifications-and-settings",["Notifications: keep the alerts that matter, quiet the rest","The Activity feed is your to-do list","Notification settings: banner, feed, or off","Mute a chat, set channel notifications","Set up your headset and make a test call","A notification plan for the front desk"]),sections:[{heading:"Too many pings",blocks:[{type:"scenario",role:"You are the front office assistant at Lakeside Medical Associates.",text:"By 10:00 AM you have had 26 pop-up banners: lunch orders, potluck sign-ups, and reactions to a message you sent yesterday. In the middle of them was Maria's question about Friday coverage, and you almost missed it. Your new headset also arrived, and your first call with IT is this afternoon.",task:"Set up notifications so the messages that need you stand out, and get your headset working before the call."},{type:"paragraph",text:"Teams can tell you about something in two places: a banner (a pop-up on your screen) and the Activity feed. The Activity feed keeps a list of @mentions, replies to your posts, reactions, and missed calls. Banners interrupt you; the feed waits for you. A good notification plan sends the important things to both and the nice-to-know things to the feed only, or nowhere."},{type:"list",items:["Open Activity on the app bar to catch up. Unread items are bold; select one to jump to the exact message.","Use the filters at the top of the feed (such as Unread and @Mentions) to see only what needs you.","An @mention of your name is the clearest sign that someone needs an answer from you."]}]},{heading:"Choose where each notification appears",blocks:[{type:"paragraph",text:"Select Settings and more (…) next to your picture › Settings › Notifications and activity. For each kind of notification you can choose where it appears or turn it off. You also set meeting notifications here, such as alerts when a meeting starts and notifications for meeting chats."},{type:"table",caption:"A notification plan for the front desk (the kinds of notifications in Settings › Notifications and activity › Chats and channels and Meetings)",columns:["Kind of notification","Suggested setting","Why"],rows:[["Mentions of me","Activity feed and banner","Someone needs an answer from you"],["Chat messages","Activity feed and banner","Most chats at work are questions for you"],["Replies to my posts","Activity feed and banner","Follow-ups on what you started"],["Reactions to my messages","Off (or Activity feed only)","Nice to see, rarely needs action"],["Meeting chat","Activity feed only","Meeting chats can be busy; read them when you join"]]},{type:"paragraph",text:"Two quicker controls handle individual conversations. To quiet one chat, point to it, select More options (…) › Mute. You stop getting notifications but can still read it. For a channel, point to it and select More options (…) › Channel notifications. You can turn notifications for new posts on or off and choose whether they appear as a banner and in the feed or only in the feed."},{type:"drag-drop",mode:"sort",title:"Banner, feed, or off?",prompt:"Sort each notification into the setting that fits a front office assistant.",buckets:[{id:"both",label:"Activity feed and banner"},{id:"feed",label:"Activity feed only"},{id:"off",label:"Off or muted"}],items:[{id:"a",text:"Maria @mentions you about Friday coverage",bucket:"both"},{id:"b",text:"A new chat message from Dr. Shah",bucket:"both"},{id:"c",text:"Someone reacted with a thumbs up to your message",bucket:"off"},{id:"d",text:"Every new post in the Staff Events channel",bucket:"off"},{id:"e",text:"New messages in the chat for a meeting you are invited to",bucket:"feed"},{id:"f",text:"Lunch orders in the Front Desk Lunch Orders chat",bucket:"off"}],explanation:"Interrupt yourself only for things that need you now. Everything else can wait in the feed or be muted."}]},{heading:"Set up your audio before the first call",blocks:[{type:"paragraph",text:"Plug in your headset, then open Settings and more (…) › Settings › Devices. Choose the headset in the Speaker list and in the Microphone list, check Noise suppression, and select Make a test call. Teams asks you to record a short message and plays it back, then shows the results for your microphone, speaker, camera, and network. Fixing a wrong microphone here takes ten seconds; fixing it in front of six people on a call takes much longer."},{type:"worked-example",title:"Getting ready for the 2:00 PM call with IT",task:"Make sure the new headset works before the call starts.",steps:[{move:"Open Settings and more (…) › Settings › Devices.",why:"Devices is where Teams decides which speaker, microphone, and camera to use for every call and meeting."},{move:"Choose Headset Earphone (Jabra Evolve2 40) as the speaker and Headset Microphone (Jabra Evolve2 40) as the microphone.",why:"Teams may keep using the laptop's built-in speaker and microphone until you tell it otherwise. The built-in microphone also picks up the whole waiting room."},{move:"Select Make a test call and listen to the playback.",why:"Hearing yourself confirms that both directions work before anyone else is waiting on you."}],result:"When the IT call starts, your audio works the first time.",takeaway:"Set up and test new audio equipment before the call, not during it."},{type:"callout",variant:"info",text:"While you are in Settings, look at Appearance and accessibility: you can choose Follow operating system theme, Light, or Dark. You will see more accessibility settings in Module 6."}]},{heading:"Knowledge check",blocks:[{type:"knowledge-check",question:"You want to keep reading the Front Desk Lunch Orders group chat but stop it from interrupting you. What should you do?",options:["Leave the chat","Hide the chat","Mute the chat","Turn off all notifications in Settings"],correctIndex:2,explanation:"Muting stops notifications for that chat but keeps it in your list so you can read it whenever you want.",optionRationales:["Leaving removes you from the conversation entirely.","Hiding moves it out of your list until a new message arrives; it does not stop the notifications for the next message.","Correct.","Turning everything off would also silence messages you need, like @mentions."]},{type:"knowledge-check",question:"Where do you choose the speaker and microphone Teams uses and make a test call?",options:["Settings › Devices","Settings › Appearance and accessibility","The Activity feed","Calendar › New event"],correctIndex:0,explanation:"Settings › Devices controls your speaker, microphone, camera, and noise suppression, and has Make a test call.",optionRationales:["Correct.","Appearance and accessibility controls the theme.","Activity shows notifications.","New event schedules a meeting."]}]}],challenge:[{type:"paragraph",text:"Put a notification plan into practice in the Challenge Lab below:"},{type:"list",ordered:!0,items:["Turn off notifications for the Staff Events channel.","In Settings › Notifications and activity, turn off notifications for reactions to your messages.","Set meeting chat notifications to Activity feed only.","Set your speaker and microphone to the Jabra Evolve2 40 headset.","Make a test call."]},{type:"callout",variant:"success",text:"Deliverable: Submit your Challenge Lab results page (print it or save it as a PDF) to your instructor or course folder."}]}],f=(a,b)=>b.map((b,c)=>({src:`/images/ms-office/teams/module-2/${a}/slide-${String(c+1).padStart(2,"0")}.jpg`,alt:b})),g=[{slug:"start-a-chat",title:"One-on-One and Group Chats",description:"Start a chat with one person, start and name a group chat, add people with or without the chat history, and keep your chat list organized with Pin, Mute, and Hide.",objectives:["Start a one-on-one chat with New message","Start a group chat and give it a name that says what it is for","Add someone to a group chat and decide how much history they see","Organize your chat list with Pin, Mute, and Hide"],duration:"15 min",slides:f("start-a-chat",["Chats: private conversations with one person or a small group","Start a one-on-one chat with New message","Start and name a group chat","Add people and choose how much history they see","Pin, Mute, and Hide: keep the chat list under control","Quick check: which chat would you start?"]),sections:[{heading:"Who needs to be in the conversation?",blocks:[{type:"scenario",role:"You are the front office assistant at Lakeside Medical Associates.",text:"The label printer at check-in is jammed again. Room 3 is low on gloves and exam table paper, and the afternoon patients start at 2:00. Maria is waiting to hear whether you can take the noon shift. Three problems, three different groups of people.",task:"Start the right chat for each problem, with exactly the people who can solve it."},{type:"paragraph",text:"A chat is a private conversation. Only the people in it can see the messages. Use a one-on-one chat for something between you and one person, and a group chat when a few people need to work something out together. If the whole team needs the information, or will need to find it later, it belongs in a channel instead (Module 3)."},{type:"list",ordered:!0,items:["Select New message at the top of your list of chats and channels (or press Ctrl+N).","In To, type a name and select the person from the list. Add more names for a group chat (a group chat can include up to 250 people).","To name a group chat, select the down arrow at the far right of To and type a Group name.","Type your message in the box at the bottom and press Enter (or select Send)."]},{type:"callout",variant:"info",text:"If you already have a one-on-one chat with someone, New message takes you to that same chat. Teams keeps one ongoing chat per person, so your whole history with them is in one place."}]},{heading:"Name group chats and add the right people",blocks:[{type:"paragraph",text:"An unnamed group chat shows up in your list as a string of first names, which is hard to find a week later. A name such as “Room 3 Restock” or “Friday Coverage” says what the chat is for. Name it when you start it."},{type:"paragraph",text:"To bring someone into an existing group chat, select View and add participants (the person icon at the top right of the chat) › Add people, type the name, and select Add. For a group chat, Teams asks how much of the earlier conversation the new person should see. Choose based on what they need: someone joining to help with the restock does not need to read last week's messages, but your manager stepping in to make a decision probably does. You cannot share history when you add someone to a one-on-one chat; Teams starts a new group chat instead."},{type:"worked-example",title:"Setting up the Room 3 restock",task:"Get gloves and exam table paper into Room 3 before 2:00 PM.",steps:[{move:"New message › To: Marcus Bell and Tasha Greene.",why:"Marcus and Tasha work in the clinical area and can check the room. Adding the whole front office would only add noise."},{move:"Select the down arrow at the far right of To and type the Group name “Room 3 Restock.”",why:"The name tells everyone what the chat is for, and it is easy to find in the list and in Search later."},{move:"Send: “Room 3 needs gloves and exam table paper before the 2:00 PM patients.”",why:"One message says what is needed, where, and by when. Nobody has to ask a follow-up question."},{move:"When Omar offers to carry the boxes, add him with View and add participants › Add people, and choose not to include the history.",why:"Omar only needs to know what to carry now. The earlier back-and-forth would not help him."}],result:"Four people, one named chat, and the room is stocked before the afternoon patients arrive.",takeaway:"Invite only the people who can act, name the chat after its purpose, and add people with the history they actually need."}]},{heading:"Keep your chat list organized",blocks:[{type:"table",caption:"Pin, Mute, and Hide (point to a chat › More options (…))",columns:["Command","What it does","Use it for"],rows:[["Pin","Moves the chat into Favorites at the top of the list","Chats you use every day, like your manager's"],["Mute","Stops notifications; the chat stays in your list","Busy social chats, such as lunch orders"],["Hide","Removes the chat from your list until someone sends a new message","Finished conversations you want out of the way"],["Mark as unread","Shows the chat in bold again","A reminder to come back and answer"]]},{type:"drag-drop",mode:"match",title:"Pin, Mute, Hide, or Mark as unread?",prompt:"Drag each command onto the situation it fits.",items:[{id:"a",text:"Your chat with Maria, which you check all day",match:"Pin"},{id:"b",text:"The lunch-order chat that pings every few minutes",match:"Mute"},{id:"c",text:"Last month's chat about a holiday party that is over",match:"Hide"},{id:"d",text:"A question from Kevin you will answer after the line clears",match:"Mark as unread"}],explanation:"Pin what you need close, mute what is noisy, hide what is finished, and mark as unread what you still owe someone an answer on."}]},{heading:"Knowledge check",blocks:[{type:"knowledge-check",question:"Omar is joining the Friday Coverage group chat so he can help decide who calls which patients. The earlier messages list the times already covered. What should you do when you add him?",options:["Start a new chat without Maria and Jen","Add him and include the chat history","Add him and don't include any history","Forward every earlier message to him one at a time"],correctIndex:1,explanation:"He needs the earlier messages to make the decision, so include the history when you add him.",optionRationales:["Splitting the conversation means the group no longer sees the same messages.","Correct.","Without the history, Omar would have to ask for everything that was already decided.","Forwarding one by one is slow and clutters his chat list. Including history does it in one step."]},{type:"knowledge-check",question:"Which is the best name for a group chat about covering the check-in window while Omar is on vacation?",options:["Chat","Omar, Jen, Tasha","Check-in Coverage: Omar's Vacation","URGENT!!!"],correctIndex:2,explanation:"A good name says what the chat is for, so anyone can find it and know why they are in it.",optionRationales:["Every chat is a chat; this says nothing.","This is what Teams shows when there is no name. It does not say what the chat is about.","Correct.","Shouting in a name is unprofessional and does not describe the topic."]}]}],challenge:[{type:"paragraph",text:"Dr. Shah is out Friday afternoon and her patients need to be rescheduled. Organize the conversation in the Challenge Lab below:"},{type:"list",ordered:!0,items:["Start a group chat with Omar Haddad and Jen Cole named “Friday Coverage.” Send: “Dr. Shah is out Friday afternoon. Can we split the reschedule calls?”","Add Maria Santos to the Friday Coverage chat and include all chat history.","Pin the Friday Coverage chat.","Start a one-on-one chat with Renee Walker and send: “Hi Renee, I finished the annual privacy training.”","Hide the Front Desk Lunch Orders chat."]},{type:"callout",variant:"success",text:"Deliverable: Submit your Challenge Lab results page (print it or save it as a PDF) to your instructor or course folder."}]},{slug:"write-clear-messages",title:"Write Clear Messages: Formatting, @Mentions, and Delivery Options",description:"Write chat messages that people can act on: use formatting and lists, @mention the right person, mark urgent information as Important, and share only the patient information someone needs.",objectives:["Use Format to add bold text and bulleted or numbered lists, and Shift+Enter for a new line","@mention a person so they get a notification","Mark a message as Important with Set delivery options","Apply the minimum necessary rule to messages about patients"],duration:"18 min",slides:f("write-clear-messages",["Messages people can act on","Format: bold, lists, and new lines","@mentions get the right person's attention","Set delivery options: mark a message Important","Minimum necessary: only the patient information someone needs","Before you press Enter: a five-second checklist"]),sections:[{heading:"A message should do one job",blocks:[{type:"scenario",role:"You are the front office assistant at Lakeside Medical Associates.",text:"Kevin asked what to bring to the billing meeting. Maria wants confirmation of the noon shift. The fire alarm test is at 3:00 PM and somebody needs to warn the waiting room. Tasha needs to know the 10:30 patient is ready for vitals. Each of these takes one short message, if it is written well.",task:"Write messages that are easy to read, reach the right person, and share no more patient information than needed."},{type:"paragraph",text:"Chat feels casual, but at work it is still business writing. A good chat message is short, gives the key detail first, and makes the next step obvious. If someone has to ask “Which shift?” or “Which room?”, the message did not do its job."},{type:"table",caption:"Rewrite for clarity",columns:["Unclear","Clear"],rows:[["“ok”","“Yes, I'll cover the check-in window from 12:00 to 1:00 PM.”"],["“the thing is broken again”","“The label printer at check-in is jammed again. Could you take a look?”"],["“can u check rm”","“Can you check whether Room 3 has gloves before the 2:00 PM patients?”"]]}]},{heading:"Formatting and lists",blocks:[{type:"paragraph",text:"Select Format, to the right of the message box, to see formatting options such as Bold, Italic, Strikethrough, Bulleted list, and Numbered list. Ctrl+B and Ctrl+I also work while you type. Press Shift+Enter to start a new line without sending; pressing Enter on its own sends the message. To get a bigger box for a longer message, select Format or press Ctrl+Shift+X."},{type:"list",items:["Bold one key detail, such as a time or a room, so it stands out. Bolding everything means nothing stands out.","Use a bulleted list for items in any order, such as things to bring.","Use a numbered list for steps that happen in order.","Keep emoji for friendly moments, not for important instructions."]},{type:"drag-drop",mode:"order",title:"Put the steps in order",prompt:"Drag the steps for sending Kevin a bulleted list into the right order.",items:[{id:"1",text:"Type “Bring these to the billing meeting:”"},{id:"2",text:"Press Shift+Enter to start a new line"},{id:"3",text:"Select Format › Bulleted list"},{id:"4",text:"Type each item, pressing Shift+Enter between them"},{id:"5",text:"Press Enter to send"}],explanation:"Shift+Enter adds a line without sending. Enter on its own sends the message."}]},{heading:"@mentions and Important messages",blocks:[{type:"paragraph",text:"Type @ followed by the first few letters of a name, then pick the person from the list. The name turns into a highlighted @mention, and that person gets a notification in their Activity feed, even in a busy channel. @mention people when you need something from them, not to tag everyone on every message."},{type:"paragraph",text:"When a message must not be missed, mark it Important before you send it: select Actions and apps (+) next to the message box › Set delivery options › Important. The message appears with the label IMPORTANT! To remove the label from a message you already sent, edit the message and choose Standard. Save Important for messages that truly are, or people learn to ignore it."},{type:"worked-example",title:"Warning about the fire alarm test",task:"Make sure Maria knows to warn the waiting room before the 3:00 PM fire alarm test.",steps:[{move:"Open the chat with Maria and select Actions and apps (+) › Set delivery options › Important.",why:"This is time-sensitive and affects patients. The IMPORTANT! label makes it stand out from routine messages."},{move:"Type: “The fire alarm test is at 3:00 PM today. Please warn patients in the waiting room.”",why:"It says what happens, when, and what you need Maria to do."},{move:"Press Enter.",why:"Done in one message. No follow-up needed."}],result:"Maria sees a clearly marked message with the time and the action.",takeaway:"Key detail first, one clear request, and Important only when it truly matters."}]},{heading:"Patient information: minimum necessary",blocks:[{type:"callout",variant:"warning",text:"HIPAA's minimum necessary standard means sharing only the patient information someone needs to do their job. In Teams at Lakeside, that usually means no patient names with health details, no dates of birth, and no diagnoses. Refer to patients the way the office allows, such as by appointment time and room. Clinical details belong in the EHR."},{type:"table",caption:"Rewrite to the minimum necessary",columns:["Too much","Minimum necessary"],rows:[["“Mrs. [name], DOB [date], is here for her diabetes follow-up and is in Room 2.”","“The 10:30 patient is checked in and ready for vitals in Room 2.”"],["“Can you call [name] about his positive test result?”","“There is a callback in the EHR task list for you.”"]]},{type:"drag-drop",mode:"sort",title:"Okay to send in a Teams chat at Lakeside?",prompt:"Sort each message.",buckets:[{id:"ok",label:"Okay to send"},{id:"no",label:"Rewrite it first"}],items:[{id:"a",text:"The 10:30 patient is ready for vitals in Room 2.",bucket:"ok"},{id:"b",text:"[Patient name] is here about her pregnancy test results.",bucket:"no"},{id:"c",text:"Room 3 needs gloves before 2:00 PM.",bucket:"ok"},{id:"d",text:"Here is [patient name]'s date of birth and insurance number for the claim.",bucket:"no"},{id:"e",text:"There is a new callback in the EHR task list for you.",bucket:"ok"}],explanation:"Messages about schedules, rooms, and supplies are fine. Anything that ties a patient's identity to health or insurance details stays in the EHR."}]},{heading:"Knowledge check",blocks:[{type:"knowledge-check",question:"You are typing a list in a chat and want to start the next line without sending the message. What do you press?",options:["Enter","Shift+Enter","Ctrl+Enter","Tab"],correctIndex:1,explanation:"Shift+Enter starts a new line. Enter alone sends the message.",optionRationales:["Enter sends the message.","Correct.","Ctrl+Enter is not how you add a line in Teams chat.","Tab moves to the next control."]},{type:"knowledge-check",question:"How do you mark a chat message as Important before sending it?",options:["Type IMPORTANT in capital letters","Actions and apps (+) › Set delivery options › Important","Pin the message","Bold the whole message"],correctIndex:1,explanation:"Set delivery options › Important adds the IMPORTANT! label that Teams displays on the message.",optionRationales:["Capital letters read as shouting and do not add the Important label.","Correct.","Pinning keeps a message at the top of the chat but does not mark it Important.","Bolding everything makes the message harder to read."]}]}],challenge:[{type:"paragraph",text:"Send four clear messages in the Challenge Lab below:"},{type:"list",ordered:!0,items:["In your chat with Kevin Patel, send “Three copays were collected at check-out today, not at check-in.” with “not at check-in” in bold.","In your chat with Maria Santos, send a numbered list with the heading “Before the huddle:” and the items “Print the schedule” and “Check the voicemail.”","In the Billing Questions channel, reply to Kevin's reminder and @mention him: “@Kevin Patel Thanks, I updated the check-in checklist.”","Mark a message to Tasha Greene as Important and send: “Room 2 is out of gloves. I'm bringing a new box now.”","In a Word document or on paper, rewrite this message to the minimum necessary: “[Patient name], born in 1958, is in Room 4 waiting for her mammogram results.”"]},{type:"callout",variant:"success",text:"Deliverable: Submit your Challenge Lab results page (print it or save it as a PDF) and your rewritten message to your instructor or course folder."}]},{slug:"react-reply-and-manage",title:"React, Reply, Edit, and Keep Track of Messages",description:"Acknowledge messages with reactions, reply to a specific message, fix mistakes with Edit and Delete, and use Pin for everyone, Save this message, Mark as unread, and Search to keep track of what matters.",objectives:["Use a reaction instead of a one-word reply, and pick from More reactions","Reply to a specific message so your answer quotes it","Edit a message you sent, and delete (or undo deleting) one sent by mistake","Keep track of messages with Pin for everyone, Save this message, Mark as unread, and Search"],duration:"18 min",slides:f("react-reply-and-manage",["Fewer messages, clearer chats","Reactions: acknowledge without adding a message","Reply to a specific message","Edit and Delete: fix your mistakes","Pin for everyone, Save, and Mark as unread","Find it again: Search and the Saved list"]),sections:[{heading:"Acknowledge without adding clutter",blocks:[{type:"scenario",role:"You are the front office assistant at Lakeside Medical Associates.",text:"Your lunch-order chat has 31 messages, and 14 of them say “ok” or “thanks.” The question you needed to answer is buried in the middle. You also just noticed that the message you sent Tasha was meant for the potluck chat.",task:"Use reactions, replies, and message tools so conversations stay short and easy to follow, and fix your own mistakes cleanly."},{type:"paragraph",text:"Point to a message and Teams shows a small bar with up to five quick reactions, such as \uD83D\uDC4D Like and ❤️ Heart. Select one and it appears under the message. Select More reactions (the smiley face) to pick from many more, such as ✅. Select a reaction you already added to remove it. You can add several different reactions to one message (up to 20). A reaction tells the sender “seen and understood” without starting a new message that everyone has to read."},{type:"paragraph",text:"When you need to answer a specific earlier message, point to it and choose Reply from More options (…). Your answer appears with a quote of the original, so nobody has to guess what “Turkey on wheat” is answering."}]},{heading:"Fix mistakes",blocks:[{type:"table",caption:"Changing a message you sent",columns:["To","Do this","What others see"],rows:[["Fix a typo or detail","Point to the message › Edit (pencil). Change it and select Done.","Your corrected message, marked Edited"],["Remove a message","Point to it › More options (…) › Delete","This message has been deleted."],["Bring it back","Select Undo on the deleted message","The original message"]]},{type:"callout",variant:"warning",text:"Deleting a message is not a privacy fix. If you sent patient information to the wrong person, delete the message and then tell your supervisor or privacy officer, following Lakeside's policy. Someone may have already read it or received a notification with a preview."},{type:"worked-example",title:"The message that went to the wrong chat",task:"“See you at the potluck!” went to Tasha instead of the Staff Events channel.",steps:[{move:"In the chat with Tasha, point to the message › More options (…) › Delete.",why:"The message is not for Tasha, and leaving it would confuse her."},{move:"Post the message where it belongs.",why:"Deleting fixes the wrong chat; you still need to say it in the right place."},{move:"If the wrong message had contained patient details, report it as well.",why:"A notification preview may already have shown the content. Reporting it is part of the fix."}],result:"Tasha's chat is clean and the message is where it belongs.",takeaway:"Edit fixes words; Delete removes a message from the chat; neither one erases what someone may already have seen."}]},{heading:"Keep track of what matters",blocks:[{type:"table",caption:"Tools for finding messages again (point to a message › More options (…))",columns:["Command","What it does"],rows:[["Pin for everyone","Shows the message at the top of the chat for everyone. Only one message is pinned at a time; Unpin for everyone removes it."],["Save this message","Adds the message to the Saved section at the top of your chat list (only you see it)."],["Mark as unread","Turns the message bold again so you remember to come back to it."],["Copy link","Copies a link to the exact message to paste somewhere else."],["Forward","Sends a copy of the message to another chat, with an optional note."]]},{type:"paragraph",text:"To find an older message, use Search at the top of Teams (Ctrl+E). Type a few words you remember, such as “holiday schedule,” and choose a result. Saved messages also appear in the Saved section of your chat list."},{type:"drag-drop",mode:"match",title:"Which tool?",prompt:"Drag each tool onto the job it does.",items:[{id:"a",text:"Everyone in the chat should always see the shift times at the top",match:"Pin for everyone"},{id:"b",text:"You want your own bookmark to Kevin's copay reminder",match:"Save this message"},{id:"c",text:"You read a question but cannot answer it until after lunch",match:"Mark as unread"},{id:"d",text:"You typed 1:00 instead of 12:00 in a message you sent",match:"Edit"},{id:"e",text:"You need to acknowledge a message without writing back",match:"Reaction"}],explanation:"Each tool keeps the chat shorter or helps you find something again without scrolling."}]},{heading:"Knowledge check",blocks:[{type:"knowledge-check",question:"Maria posts the week's shift times in a group chat and wants everyone to see them at the top of the chat. What should she use?",options:["Save this message","Pin for everyone","Mark as unread","Copy link"],correctIndex:1,explanation:"Pin for everyone shows the message at the top of the chat for everyone in it.",optionRationales:["Save is a personal bookmark; others do not see it.","Correct.","Mark as unread only affects Maria's own view.","Copy link copies a link; it does not keep the message visible."]},{type:"knowledge-check",question:"You deleted a message by mistake a moment ago. How do you get it back?",options:["It is gone forever","Select Undo on the deleted message","Ask IT to restore it","Forward it to yourself"],correctIndex:1,explanation:"Teams shows Undo on a message you deleted, which brings it back.",optionRationales:["Teams lets you undo a delete.","Correct.","You can undo it yourself.","You cannot forward a deleted message."]}]}],challenge:[{type:"paragraph",text:"Work through your chats in the Challenge Lab below:"},{type:"list",ordered:!0,items:["React to Tasha's thank-you message with Heart.","In Front Desk Lunch Orders, reply to Omar's message so it is quoted: “Got it, chicken wrap for Omar.”","Edit your message in Maria's chat to say “Yes, I can cover the window from 12:00 to 1:00.”","Mark Kevin's message as unread so you remember to come back to it.","Save Maria's message about the check-in window."]},{type:"callout",variant:"success",text:"Deliverable: Submit your Challenge Lab results page (print it or save it as a PDF) to your instructor or course folder."}]},{slug:"share-files-in-chat",title:"Share Files in Chat",description:"Attach files from the cloud or your computer, find shared files on a chat's Shared tab, understand where Teams stores chat files and who can open them, and forward messages and links.",objectives:["Attach a cloud file or upload a file from your device with Actions and apps › Attach file","Find files shared in a chat on its Shared tab","Explain where Teams stores chat files (Microsoft Teams Chat Files in your OneDrive) and who can open them","Forward a message and copy a link to a message"],duration:"15 min",slides:f("share-files-in-chat",["Share the one real file, not copies","Attach file: cloud files or upload from this device","Where chat files go: Microsoft Teams Chat Files in your OneDrive","Who can open a file you shared in chat","The Shared tab, Forward, and Copy link","Files and patient information"]),sections:[{heading:"Share files where the conversation is",blocks:[{type:"scenario",role:"You are the front office assistant at Lakeside Medical Associates.",text:"Jen Cole, the temporary receptionist, starts today and needs the front desk procedures. The Holiday Coverage chat is waiting for the draft schedule you saved on your computer. Last year someone emailed the schedule to six people, everyone edited their own copy, and nobody knew which version was right.",task:"Share each file with the people who need it, in the conversation where they are already talking."},{type:"list",ordered:!0,items:["In the chat, select Actions and apps (+) next to the message box › Attach file.","Pick a recent file, choose Attach cloud files to pick a file from OneDrive or Teams, or choose Upload from this device for a file on your computer.","Add a short message that says why you are sharing it, and press Enter."]},{type:"paragraph",text:"Teams shows a preview for images, videos, and many document types. Every file shared in a chat is collected on the chat's Shared tab at the top of the conversation, so nobody has to scroll back through messages to find it."}]},{heading:"Where chat files are stored",blocks:[{type:"paragraph",text:"When you upload a file in a one-on-one or group chat, Teams saves it in your OneDrive, in a folder named Microsoft Teams Chat Files, and shares it only with the people in that chat. Files shared in a channel are different: they are stored in the team's SharePoint site and appear on the channel's Shared tab (Module 3). This is why it matters where you share: a file you upload in chat lives in your OneDrive, and if you leave the organization, files in your OneDrive can be removed along with your account."},{type:"table",caption:"Chat files and channel files",columns:["","Shared in a chat","Shared in a channel"],rows:[["Stored in","Your OneDrive › Microsoft Teams Chat Files","The team's SharePoint site"],["Who can open it","The people in that chat","Members of the team"],["Find it on","The chat's Shared tab","The channel's Shared tab"],["Best for","A file for a few people","Files the whole team uses and keeps"]]},{type:"drag-drop",mode:"sort",title:"Chat or channel?",prompt:"Where should each file be shared?",buckets:[{id:"chat",label:"In a chat"},{id:"channel",label:"In a channel"}],items:[{id:"a",text:"Your draft of a reminder script, for Maria to review",bucket:"chat"},{id:"b",text:"The final New Patient Intake Packet everyone uses",bucket:"channel"},{id:"c",text:"A spreadsheet of wait times for the three people planning holiday coverage",bucket:"chat"},{id:"d",text:"The copay quick reference for the whole front office",bucket:"channel"}],explanation:"Drafts and files for a few people fit in a chat. Files the team uses and needs to keep belong in the team's channel."}]},{heading:"Forward and link to messages",blocks:[{type:"paragraph",text:"To pass a message along, point to it › More options (…) › Forward, choose the person or chat, add an optional note, and select Forward. To point someone to a message instead of copying it, choose Copy link and paste the link where you need it. Only people who can already see that chat or channel can open a message link."},{type:"worked-example",title:"Getting the schedule to the holiday group",task:"Share the draft holiday schedule from your computer with the Holiday Coverage chat.",steps:[{move:"Open the Holiday Coverage chat and select Actions and apps (+) › Attach file › Upload from this device.",why:"The file is on your computer, so you upload it. Teams stores the uploaded copy in your OneDrive."},{move:"Pick Holiday Coverage Schedule.xlsx and type: “Here is the draft. Add your name to the days you can work.”",why:"The message says what the file is and exactly what you want people to do with it."},{move:"Press Enter, then check OneDrive › My files › Microsoft Teams Chat Files.",why:"That folder holds the copy everyone in the chat opens. From now on, edit that one, not the copy on your desktop."}],result:"Three coworkers edit the same file, and there is only one version of the schedule.",takeaway:"Share one file in the conversation and work on that file; do not pass copies around."},{type:"callout",variant:"warning",text:"Before you attach a file, check its contents. Files with patient information belong only in the locations Lakeside approves and only with people who need them. Never upload patient lists or forms to a group chat that includes people who do not need them, or to any chat with someone outside Lakeside."}]},{heading:"Knowledge check",blocks:[{type:"knowledge-check",question:"You upload a spreadsheet in a group chat. Where does Teams store it?",options:["On your computer's desktop","In your OneDrive, in the Microsoft Teams Chat Files folder","In every chat member's Downloads folder","In the Front Office team's SharePoint site"],correctIndex:1,explanation:"Files uploaded in chats are stored in the sender's OneDrive, in Microsoft Teams Chat Files, and shared with the people in the chat.",optionRationales:["Teams uploads a copy to the cloud; the chat does not use your desktop copy.","Correct.","Nobody gets a download unless they choose to download it.","Channel files go to the team's SharePoint site; chat files do not."]},{type:"knowledge-check",question:"Where do you look for every file that was shared in a particular chat?",options:["The chat's Shared tab","The Activity feed","Calendar","Settings"],correctIndex:0,explanation:"The Shared tab at the top of the chat lists the files shared in that conversation.",optionRationales:["Correct.","Activity lists notifications, not files.","Calendar lists meetings.","Settings holds preferences."]}]}],challenge:[{type:"paragraph",text:"Share files and messages in the Challenge Lab below:"},{type:"list",ordered:!0,items:["In your chat with Maria Santos, attach “Reminder Call Script.docx” from your cloud files and send: “Here is the updated reminder call script for your review.”","In the Holiday Coverage chat, upload “Lobby Wait Times - October.xlsx” from your device and send: “October wait times, for our planning.”","Open “Lobby Wait Times - October.xlsx” from the Microsoft Teams Chat Files folder in OneDrive.","Forward Maria's message about the check-in window to Omar Haddad with the note “FYI for Friday.”"]},{type:"callout",variant:"success",text:"Deliverable: Submit your Challenge Lab results page (print it or save it as a PDF) to your instructor or course folder."}]}],h=(a,b)=>b.map((b,c)=>({src:`/images/ms-office/teams/module-3/${a}/slide-${String(c+1).padStart(2,"0")}.jpg`,alt:b})),i=[{slug:"teams-and-channels",title:"Teams and Channels: Where Team Conversations Live",description:"Learn how teams and channels are organized, how to join a team, the difference between the Posts and Threads channel layouts, and when a conversation belongs in a channel instead of a chat.",objectives:["Explain how a team, its channels, and the General channel are organized, and what team owners do","Join a team with New items › Join team","Describe the Posts and Threads channel layouts","Decide whether a message belongs in a channel or a chat"],duration:"15 min",videoUrl:"https://www.youtube.com/embed/m3VLT084vik",slides:h("teams-and-channels",["Teams and channels: the team's shared conversations","How a team is organized","Join a team: New items › Join team","Two channel layouts: Posts and Threads","Channel or chat? Ask who needs it and for how long","Being a good team member in channels"]),sections:[{heading:"Teams, channels, and the people in them",blocks:[{type:"scenario",role:"You are the front office assistant at Lakeside Medical Associates.",text:"Maria asks you to join the Patient Experience Committee, a team of nine people from the front desk, clinical staff, and billing who meet monthly to make visits smoother. Between meetings, all of their ideas, decisions, and files live in the team's channels. If you post your ideas in a private chat with Maria, the rest of the committee never sees them.",task:"Join the team, find your way around its channels, and put each message where the team can use it."},{type:"paragraph",text:"A team is a group of people who work together, such as the Front Office team or a committee. Every team has channels, and every team starts with a General channel for announcements and anything that does not fit elsewhere. Other channels are organized by topic: Scheduling, Billing Questions, Ideas. Members of the team can read and post in its standard channels, and a team can also have private channels for a smaller group of its members."},{type:"key-terms",terms:[{term:"Team owner",definition:"Manages the team: who is a member, what channels exist, and team settings."},{term:"Team member",definition:"Can read and post in the team's standard channels."},{term:"General channel",definition:"The channel every team has, for team-wide announcements and general topics."},{term:"Standard channel",definition:"A channel every member of the team can see."},{term:"Private channel",definition:"A channel only some members of the team are added to."}]},{type:"list",ordered:!0,items:["In Chat, select the arrow next to New message at the top of the list (New items) and choose Join team. In the Separate view, select Teams first.","Type the team's name or topic in the search box.","Point to the team's tile and select Join team. (Some teams are private; for those you ask the owner to add you, or join with a code the owner gives you.)"]}]},{heading:"Posts layout and Threads layout",blocks:[{type:"paragraph",text:"Channels come in two layouts, chosen when the channel is created (a channel owner can change it later in Edit channel). In the Posts layout, each conversation starts as a post, often with a subject, and replies are tucked under it; it works well for announcements and updates that many people need to see. In the Threads layout, the channel looks more like a group chat: you type at the bottom and press Send, and side conversations happen in threads with Reply in thread. This course practices the Posts layout; school accounts use it for every channel."},{type:"table",caption:"Posts layout and Threads layout",columns:["","Posts layout","Threads layout"],rows:[["Start a conversation","Start a post (add a subject), then Post","Type in the box at the bottom, then Send"],["Answer","Reply under the post","Reply in thread"],["Feels like","A bulletin board with comment threads","A group chat with side threads"],["Good for","Announcements and updates for many people","Fast back-and-forth discussion"]]}]},{heading:"Channel or chat?",blocks:[{type:"paragraph",text:"Two questions decide it. Who needs to see this? If it is the whole team, or people who are not in the conversation yet, use the channel. How long will it matter? If someone will need to find it next month, a channel post is searchable for everyone on the team. A private question, a personal request, or a quick check with one or two people goes in a chat."},{type:"drag-drop",mode:"sort",title:"Channel or chat?",prompt:"Sort each message for the Patient Experience Committee.",buckets:[{id:"channel",label:"Channel post"},{id:"chat",label:"Chat"}],items:[{id:"a",text:"An idea for a wait-time sign at check-in",bucket:"channel"},{id:"b",text:"Asking Maria whether committee meetings count as work hours",bucket:"chat"},{id:"c",text:"The final agenda for next month's committee meeting",bucket:"channel"},{id:"d",text:"Telling Tasha you'll be two minutes late to walk over together",bucket:"chat"},{id:"e",text:"Survey results the whole committee will discuss",bucket:"channel"}],explanation:"Team ideas, decisions, and documents go in the channel so every member sees them and can find them later. Personal questions and quick logistics go in a chat."},{type:"worked-example",title:"First day on the committee",task:"Join the Patient Experience Committee and contribute without cluttering it.",steps:[{move:"New items › Join team › Patient Experience Committee › Join team.",why:"Joining gives you every channel's history, so you can read what the committee already decided."},{move:"Reply to Maria's welcome post in General instead of starting a new post.",why:"She asked new members to introduce themselves under her post. Replies keep every introduction in one place."},{move:"Start a post in Ideas with the subject “Wait-time sign.”",why:"Each idea gets its own post and subject, so the committee can discuss it in the replies and find it later."},{move:"Ask your work-hours question in a chat with Maria.",why:"It is about your own schedule. The other eight members do not need it."}],result:"The committee sees your introduction and your idea; your personal question stays private.",takeaway:"Reply where you were asked, start a new post for a new topic, and keep personal questions in chat."}]},{heading:"Knowledge check",blocks:[{type:"knowledge-check",question:"Which channel does every team have?",options:["Announcements","General","Ideas","Files"],correctIndex:1,explanation:"Every team starts with a General channel. Other channels are created by the team.",optionRationales:["Some teams create an Announcements channel, but not every team.","Correct.","Ideas is a channel this committee created.","Files are on each channel's Shared tab; Files is not a channel."]},{type:"knowledge-check",question:"In a Threads layout channel, how do you answer one specific message without adding to the main conversation?",options:["Start a post","Reply in thread","Forward it","Pin it"],correctIndex:1,explanation:"Reply in thread starts or continues a side conversation under that message.",optionRationales:["That starts a new conversation.","Correct.","Forwarding sends a copy somewhere else.","Pinning keeps it visible; it does not answer it."]}]}],challenge:[{type:"paragraph",text:"Join the committee and take part in the Challenge Lab below:"},{type:"list",ordered:!0,items:["Join the team “Patient Experience Committee.”","Reply to Maria's welcome post in the team's General channel: “Hi all, Alex here from the front desk.”","In the Ideas channel, start a post with the subject “Clipboard station” and the message “A self-serve clipboard station would shorten the check-in line.”","Reply to Omar's idea in the Ideas channel: “Great idea. Reminder texts could include a running-late notice.”"]},{type:"callout",variant:"success",text:"Deliverable: Submit your Challenge Lab results page (print it or save it as a PDF) to your instructor or course folder."}]},{slug:"posts-and-replies",title:"Post, Reply, and Announce in Channels",description:"Start posts with clear subjects, keep answers in the thread, @mention the person you need, post announcements, and set channel notifications for the channels that matter to your job.",objectives:["Start a post with a subject that tells people what it is about","Reply in the thread and @mention the person who needs to act","Post an announcement with a headline","Choose channel notifications and pin the channels you use most"],duration:"18 min",videoUrl:"https://www.youtube.com/embed/ps7dDNrXI6E",slides:h("posts-and-replies",["Channel posts the whole team can use","Start a post with a subject","Reply in the thread","Announcements for news that must stand out","Channel notifications: hear about what matters","Channel etiquette"]),sections:[{heading:"Posts that people can scan",blocks:[{type:"scenario",role:"You are the front office assistant at Lakeside Medical Associates.",text:"The Scheduling channel had 40 new posts last week. Five of them were answers to Maria's question about Dr. Shah's Friday patients, posted as new posts instead of replies, so Maria could not tell which patients were already called. Two people called the same patient.",task:"Post and reply so the team can see at a glance what is new, what is answered, and who is doing what."},{type:"list",ordered:!0,items:["Go to the channel and select Start a post (or Start a new post at the top of the Posts tab).","Type a short subject that names the topic, such as “Printer fixed.”","Type the message, and @mention anyone who needs to act.","Select Post."]},{type:"paragraph",text:"Replies keep a conversation together. Select Reply under the post, type your answer, and press Enter. Everyone who reads the post sees your answer right under it. Start a new post only for a new topic."},{type:"drag-drop",mode:"sort",title:"New post or reply?",prompt:"Sort each message for the Scheduling channel.",buckets:[{id:"post",label:"Start a new post"},{id:"reply",label:"Reply to an existing post"}],items:[{id:"a",text:"“I'll call the 2:30 and 3:00 patients” (answering Maria's Dr. Shah post)",bucket:"reply"},{id:"b",text:"The provider schedule for December is ready",bucket:"post"},{id:"c",text:"“The packet looks complete” (about Omar's intake packet post)",bucket:"reply"},{id:"d",text:"The phone system will be down for an update tonight",bucket:"post"}],explanation:"If it answers or adds to something already posted, reply under it. If it is a new topic, start a new post with a clear subject."}]},{heading:"@mentions and announcements",blocks:[{type:"paragraph",text:"In a channel, an @mention is how you make sure a specific person sees your message. Type @, a few letters of the name, and pick the person. They get a notification even if they have that channel's notifications turned off. Use it for the person who must act, not for everyone you can think of."},{type:"paragraph",text:"An announcement is a post that stands out, with a large headline and an optional color scheme or background image. In a Posts layout channel, start a post and choose Announcement as the Post type (the exact button depends on how the channel orders posts). Type the headline, then the details, and post it. Use announcements for news that affects the whole team, such as new hours or an event, not for everyday updates."},{type:"worked-example",title:"Announcing the staff flu shot clinic",task:"Make sure the whole front office knows about Saturday's flu shot clinic.",steps:[{move:"Go to Front Office › General and start a post.",why:"General reaches everyone on the team, and the clinic is not about any one topic channel."},{move:"Change the Post type to Announcement and type the headline “Flu Shot Clinic Saturday.”",why:"A large headline is easy to spot when people scroll the channel."},{move:"Type “Staff flu shots are 9:00 AM to noon in Room 5.” and post it.",why:"The details people need, the time and place, are in the first line."}],result:"An eye-catching post the whole team can find later.",takeaway:"Use an announcement for team-wide news; keep everyday updates as normal posts."}]},{heading:"Channel notifications and favorites",blocks:[{type:"paragraph",text:"You decide how much each channel can interrupt you. Point to the channel, select More options (…) › Channel notifications. You can turn notifications for new posts on or off and choose whether they appear as a banner and in the Activity feed or only in the feed. Turn them on for channels your job depends on (for Alex, Scheduling) and off for channels you can read when you have time (Staff Events). @mentions of your name still reach you either way. Pin the channels you use most so they appear in Favorites."},{type:"table",caption:"Channel etiquette at Lakeside",columns:["Do","Don't"],rows:[["Give new posts a clear subject","Post “Question” or “Help” as a subject"],["Reply under the post you are answering","Start a new post to answer an old one"],["@mention the person who must act","@mention everyone on every post"],["Keep patient details in the EHR","Post patient names with health information"]]},{type:"callout",variant:"warning",text:"Everyone on the team can read a standard channel, and some teams include guests from outside Lakeside. Never post patient names with health details, dates of birth, or insurance numbers in a channel."}]},{heading:"Knowledge check",blocks:[{type:"knowledge-check",question:"Maria posted asking who can call Dr. Shah's Friday patients. You can take two of the calls. What should you do?",options:["Start a new post saying you'll take two calls","Reply under Maria's post and @mention her or the person coordinating","Send a private chat to every front desk worker","Edit Maria's post"],correctIndex:1,explanation:"A reply keeps the answer with the question, so everyone can see which calls are taken.",optionRationales:["A separate post splits the conversation; this is how two people ended up calling the same patient.","Correct.","Private chats hide the answer from the rest of the team.","You cannot edit someone else's post."]},{type:"knowledge-check",question:"You turned off notifications for the Staff Events channel. Someone @mentions you in a post there. What happens?",options:["You never find out","You still get notified, because it is an @mention of you","The post is deleted","Teams turns channel notifications back on"],correctIndex:1,explanation:"Channel notification settings control new posts. An @mention of you still notifies you.",optionRationales:["Mentions of you still reach you.","Correct.","Notification settings never delete posts.","Your channel setting stays the same."]}]}],challenge:[{type:"paragraph",text:"Keep the team informed in the Challenge Lab below:"},{type:"list",ordered:!0,items:["In the Billing Questions channel, start a post with the subject “Card reader” and the message “The card reader at window 2 is offline. Use window 1 for copays today.”","In the Scheduling channel, reply to Omar's post about the intake packet and @mention him: “@Omar Haddad The packet looks complete. Thanks!”","In the Front Office General channel, post an announcement with the headline “New Check-In Hours” and the message “Check-in opens at 7:30 AM starting Monday.”","Turn off notifications for the Staff Events channel.","Pin the Billing Questions channel."]},{type:"callout",variant:"success",text:"Deliverable: Submit your Challenge Lab results page (print it or save it as a PDF) to your instructor or course folder."}]},{slug:"shared-tab-and-tabs",title:"The Shared Tab and Channel Tabs",description:"Find, upload, pin, and link to a channel's files on its Shared tab, understand that channel files live in the team's SharePoint site, and add apps and files as tabs at the top of a channel.",objectives:["Find a channel's files and links on its Shared tab","Upload a file to a channel, pin it to the top, and copy a link to it","Explain that channel files are stored in the team's SharePoint site","Add an app such as Planner or Lists as a tab in a channel"],duration:"15 min",slides:h("shared-tab-and-tabs",["Every channel has a Shared tab","Channel files live in the team's SharePoint site","Upload, pin to top, and copy a link","Add a tab: put a tool at the top of the channel","Where should this file go?","Quick check"]),sections:[{heading:"The Shared tab",blocks:[{type:"scenario",role:"You are the front office assistant at Lakeside Medical Associates.",text:"Omar asks for the provider schedule for the third time this week. It is in the Scheduling channel, but it was shared in a post two weeks ago and has scrolled out of sight. New hires keep using an old copy of the intake packet they saved to their desktops.",task:"Use the Shared tab so the team's files are easy to find, and keep the most-used ones at the top."},{type:"paragraph",text:"At the top of every channel are tabs. Posts shows the conversation. Shared lists the files and links shared in that channel. (In January 2026 Microsoft renamed the channel's Files tab to Shared, so older guides may still say Files.) A file posted in a channel's conversation shows up on its Shared tab too, so nobody has to scroll back through posts to find it."},{type:"paragraph",text:"Files you add to a channel are stored in the team's SharePoint site, in a folder for that channel. The team owns them: they stay when someone leaves Lakeside, and every member of the team can open them. That is the difference from chat files, which live in the sender's OneDrive (Module 2)."},{type:"table",caption:"On the Shared tab (point to a file › More options (…))",columns:["Command","What it does"],rows:[["Upload › Files","Adds a file from your computer to the channel"],["Open","Opens the file in Teams"],["Pin to top","Keeps the file at the top of the list"],["Copy link","Copies a link you can paste into a post or chat"],["Share","Shares the file with specific people"]]}]},{heading:"Add a tab",blocks:[{type:"paragraph",text:"Tabs put the tools a team uses every day one click away. Select Add a tab (+) at the top of the channel, choose an app such as Planner (a shared task plan), Lists (a tracker), or Forms (a survey), and select Add. To show a single file as a tab, first share the file in the channel, then add a tab for its app (for example, Excel), pick the file, and select Save. Posts and Shared are always there; your team owner may limit who can add or remove other tabs."},{type:"worked-example",title:"Cleaning up the Scheduling channel",task:"Make the schedule and intake packet easy to find, and give the team one place for scheduling tasks.",steps:[{move:"Open Scheduling › Shared and upload Holiday Coverage Schedule.xlsx.",why:"Uploading to the channel stores the file in the team's SharePoint site, where everyone works on the same copy."},{move:"Point to New Patient Intake Packet.pdf › More options › Pin to top.",why:"The most-used file is first in the list for everyone."},{move:"Point to Provider Schedule - November.xlsx › More options › Copy link, and paste it in your reply to Omar.",why:"A link opens the one real file. Nobody saves another copy to their desktop."},{move:"Select Add a tab (+) › Planner › Add.",why:"Reschedule calls and coverage tasks get a shared plan at the top of the channel instead of getting lost in posts."}],result:"The channel's key files are pinned and linkable, and the team has a shared task plan.",takeaway:"Put team files in the channel, pin the ones people use most, and share links, not copies."},{type:"drag-drop",mode:"sort",title:"Where should this file go?",prompt:"Sort each file.",buckets:[{id:"channel",label:"The team channel's Shared tab"},{id:"mine",label:"Your OneDrive or a chat"}],items:[{id:"a",text:"The final provider schedule the whole front office uses",bucket:"channel"},{id:"b",text:"Your rough notes from a training session",bucket:"mine"},{id:"c",text:"The approved copay quick reference",bucket:"channel"},{id:"d",text:"A draft letter you want Maria to look at before anyone else sees it",bucket:"mine"}],explanation:"Files the team relies on belong in the channel. Drafts and personal notes stay in your OneDrive or a small chat until they are ready."}]},{heading:"Knowledge check",blocks:[{type:"knowledge-check",question:"Where is a file stored when you upload it on a channel's Shared tab?",options:["In your OneDrive","In the team's SharePoint site","On your computer only","In your email"],correctIndex:1,explanation:"Channel files are stored in the team's SharePoint site, so the whole team can use them and they stay when people leave.",optionRationales:["Chat files go to your OneDrive; channel files do not.","Correct.","Uploading puts a copy in the cloud.","Teams does not store channel files in email."]},{type:"knowledge-check",question:"Older instructions tell you to open a channel's Files tab. What is it called in current Teams?",options:["Posts","Shared","Wiki","Notes"],correctIndex:1,explanation:"The channel Files tab became the Shared tab in January 2026. It lists files and links shared in the channel.",optionRationales:["Posts is the conversation.","Correct.","There is no Wiki tab for files.","Notes is not where channel files are listed."]}]}],challenge:[{type:"paragraph",text:"Organize a channel's files in the Challenge Lab below:"},{type:"list",ordered:!0,items:["Upload “Flu Clinic Flyer.pdf” to the Shared tab of the Front Office General channel.","Pin “Flu Clinic Flyer.pdf” to the top.","Copy a link to “Flu Clinic Flyer.pdf.”","Open “Copay Quick Reference.pdf” on the Billing Questions channel's Shared tab.","Close the file and add a Lists tab to the Billing Questions channel."]},{type:"callout",variant:"success",text:"Deliverable: Submit your Challenge Lab results page (print it or save it as a PDF) to your instructor or course folder."}]}],j=(a,b)=>b.map((b,c)=>({src:`/images/ms-office/teams/module-4/${a}/slide-${String(c+1).padStart(2,"0")}.jpg`,alt:b})),k=[{slug:"where-files-live",title:"Where Your Files Live: OneDrive, Chats, and Channels",description:"Learn where Teams stores every file you share, find your files with OneDrive in Teams, and keep your own files organized with folders, Move to, and Rename.",objectives:["Explain where Teams stores files shared in chats, in channels, and in your own OneDrive","Use OneDrive in Teams: Home, My files, Shared, Favorites, and the Recycle bin","Create folders, upload, move, and rename files in OneDrive","Choose the right home for a file based on who owns it"],duration:"15 min",slides:j("where-files-live",["Where your files live in Microsoft 365","Three homes for files: your OneDrive, a chat, a channel","OneDrive in Teams: Home, My files, Shared, Favorites, Recycle bin","Folders, Move to, and Rename keep My files tidy","Who owns the file decides where it lives","Quick check"]),sections:[{heading:"Three homes for a file",blocks:[{type:"scenario",role:"You are the front office assistant at Lakeside Medical Associates.",text:"Three weeks into the job, your OneDrive has eleven files with no folders, a Microsoft Teams Chat Files folder you never created, and two copies of the reminder call script. Maria asks for the latest version and you are not sure which one it is.",task:"Understand where Teams puts every file, and organize your own files so you can always find the right one."},{type:"paragraph",text:"Teams does not have its own separate file storage. Every file you see in Teams lives in one of two Microsoft 365 places: your OneDrive (files that belong to you) or a team's SharePoint site (files that belong to the team). Where a file ends up depends on where you share it."},{type:"table",caption:"Where Teams stores files",columns:["You add a file to","It is stored in","Who can open it"],rows:[["Your OneDrive (OneDrive on the app bar)","Your OneDrive › My files","You, plus anyone you share it with"],["A one-on-one or group chat","Your OneDrive › Microsoft Teams Chat Files","The people in that chat"],["A channel (post or Shared tab)","The team's SharePoint site, in the channel's folder","Members of the team"]]},{type:"image",src:"/images/ms-office/teams/module-4/where-files-live/infographic.png",alt:"Where files live in Teams: your OneDrive for your own files and chat files, the team's SharePoint site for channel files, with who can open each and how to find them",caption:"Where files live in Teams"}]},{heading:"OneDrive in Teams",blocks:[{type:"paragraph",text:"Select OneDrive on the app bar to see your work files without leaving Teams. Home lists files you recently opened or edited. My files is your OneDrive, with your folders. Shared shows files others shared with you and files you shared. Favorites holds files you starred, and the Recycle bin holds files you deleted, so you can restore them. You can also browse files by People, Meetings, or Media type, and Quick access takes you to files in your teams' channels."},{type:"list",ordered:!0,items:["To create a folder: in My files, select Add new › Folder, type a name, and select Create.","To upload: open the folder, select Upload, choose the file, and select Open.","To move a file: point to it › More options (…) › Move to, choose the folder, and select Move here.","To rename a file: point to it › More options (…) › Rename, type the new name, and press Enter."]},{type:"worked-example",title:"Cleaning up My files",task:"Put three weeks of files in order so the right version is easy to find.",steps:[{move:"Open OneDrive › My files and look inside Microsoft Teams Chat Files.",why:"That folder holds every file you uploaded in a chat. Knowing it exists explains files you do not remember saving."},{move:"Create a folder named Front Desk Training.",why:"One folder per kind of work beats eleven loose files."},{move:"Move Reminder Call Script.docx into the folder, and rename files so the name says what they are.",why:"A clear name and place mean you open the right file the first time, and so does anyone you share it with."}],result:"Your files are in named folders, and the latest script is the one in Front Desk Training.",takeaway:"Keep one copy, in one place, with a name that says what it is."}]},{heading:"Choose the right home",blocks:[{type:"drag-drop",mode:"sort",title:"Where should this file live?",prompt:"Sort each file to its best home.",buckets:[{id:"od",label:"Your OneDrive"},{id:"chat",label:"A chat with a few people"},{id:"channel",label:"A team channel"}],items:[{id:"a",text:"Your notes from phone system training",bucket:"od"},{id:"b",text:"A draft letter you want Maria to look at first",bucket:"chat"},{id:"c",text:"The final provider schedule the front office uses",bucket:"channel"},{id:"d",text:"Your personal checklist of tasks for this week",bucket:"od"},{id:"e",text:"The copay quick reference everyone follows",bucket:"channel"},{id:"f",text:"A spreadsheet for the three people planning holiday coverage",bucket:"chat"}],explanation:"Your own work stays in your OneDrive. Files for a few people can go in their chat. Files the whole team relies on, and that must stay after you leave, belong in the team's channel."},{type:"callout",variant:"warning",text:"Lakeside's rule for files with patient information: keep them only in locations the practice approves and share them only with people who need them. Never move patient files into a personal OneDrive or a personal email account, and never upload them to a channel that includes people who do not need them."}]},{heading:"Knowledge check",blocks:[{type:"knowledge-check",question:"You find a folder named Microsoft Teams Chat Files in your OneDrive. What is in it?",options:["Files other people sent you by email","Files you uploaded in Teams chats","Every file in every channel","Teams settings"],correctIndex:1,explanation:"When you upload a file in a chat, Teams stores it in your OneDrive in Microsoft Teams Chat Files and shares it with the people in that chat.",optionRationales:["Email attachments are not saved there.","Correct.","Channel files are stored in each team's SharePoint site.","Settings are not stored as files there."]},{type:"knowledge-check",question:"You deleted a file from your OneDrive by mistake. Where do you look first?",options:["The Recycle bin in OneDrive","Activity","The Calendar","A new chat"],correctIndex:0,explanation:"Deleted OneDrive files go to the Recycle bin, where you can restore them.",optionRationales:["Correct.","Activity shows notifications.","Calendar shows events.","A chat cannot restore a deleted file."]}]}],challenge:[{type:"paragraph",text:"Organize your files in the Challenge Lab below:"},{type:"list",ordered:!0,items:["In OneDrive › My files, create a folder named “Committee Work.”","Open Committee Work and upload “Flu Clinic Flyer.pdf” from your device.","Move “New Hire Checklist.docx” into Committee Work.","Rename “Reminder Call Script.docx” to “Reminder Call Script - Draft 2.docx.”","Open “Copay Quick Reference.pdf” from the Billing Questions channel's Shared tab."]},{type:"callout",variant:"success",text:"Deliverable: Submit your Challenge Lab results page (print it or save it as a PDF) to your instructor or course folder."}]},{slug:"share-with-the-right-people",title:"Share Files with the Right People and Permissions",description:"Share a file from Teams with specific people or a link, choose who the link works for and whether people can edit or only view, and apply least access to anything that touches patient information.",objectives:["Share a file from OneDrive in Teams or a channel's Shared tab and send or copy the link","Choose who a link works for: Anyone, People in your organization, People with existing access, or People you choose","Choose Can edit or Can view, and know that Can review and Can't download may also be offered","Apply least access: the narrowest link and permission that lets people do the job"],duration:"18 min",videoUrl:"https://www.youtube.com/embed/RbOkcOqlavw",slides:j("share-with-the-right-people",["Share the one real file with the right access","Share: pick people, settings, then Send or Copy link","Who the link works for","Can edit or Can view","Least access, every time","Quick check: which link would you choose?"]),sections:[{heading:"Who needs this file, and what will they do with it?",blocks:[{type:"scenario",role:"You are the front office assistant at Lakeside Medical Associates.",text:"Jen Cole, the temporary receptionist, needs to read her new-hire checklist. The whole office should be able to read the procedures, but not change them. Maria needs to edit your reminder call script. Last month a coworker sent a link that let anyone in the organization edit the copay sheet, and someone changed a price by mistake.",task:"Give each person exactly the access they need, and no more."},{type:"paragraph",text:"Sharing a file gives people a link to the one real file instead of a copy. Two decisions control what happens next: who the link works for, and whether those people can edit or only view. Microsoft sets a default for your organization, so always check the link settings before you send."},{type:"list",ordered:!0,items:["In OneDrive in Teams (or on a channel's Shared tab), point to the file and select Share (or More options (…) › Share).","Type the names of the people to share with.","Open the link settings (the line that says who the link works for) and choose who it works for and whether they can edit or view. Select Apply.","Add a short message, and select Send. Or select Copy link to paste the link into a chat or email yourself."]}]},{heading:"Link types and permissions",blocks:[{type:"table",caption:"Who the link works for",columns:["Link setting","Works for","Use it for"],rows:[["Anyone","Anyone who has the link, including people outside the practice","Public flyers only; never patient information (your organization may turn this off)"],["People in your organization","Anyone signed in to a Lakeside account","Procedures and forms everyone at the practice may read"],["People with existing access","Only people who already have access","Reminding a coworker where a file is, without giving anyone new access"],["People you choose","Only the people you name","Anything sensitive, and most files you share with one or two people"]]},{type:"paragraph",text:"Then choose the permission. Can edit lets people change the file. Can view lets them open and read it but not change it. Depending on the file and your organization, you may also see Can review (people can suggest changes and comment in Word) and Can't download (view in the browser without downloading a copy)."},{type:"drag-drop",mode:"match",title:"Pick the link",prompt:"Drag the best link setting onto each situation.",items:[{id:"a",text:"Jen must read her new-hire checklist",match:"People you choose, Can view"},{id:"b",text:"Every Lakeside employee should be able to read the procedures",match:"People in your organization, Can view"},{id:"c",text:"Maria needs to edit your draft script",match:"People you choose, Can edit"},{id:"d",text:"Reminding Omar where the schedule is (he already has access)",match:"People with existing access"}],explanation:"Name the people when you can, give view access unless they need to edit, and only widen the link when everyone in the organization truly needs it."}]},{heading:"Least access, every time",blocks:[{type:"worked-example",title:"Sharing the procedures without letting everyone edit them",task:"Let the whole office read Front Desk Procedures.docx without being able to change it.",steps:[{move:"Point to Front Desk Procedures.docx › More options (…) › Share.",why:"Share opens the link settings for this one file."},{move:"Open the link settings, choose People in Lakeside Medical Associates, and change the permission to Can view. Select Apply.",why:"Everyone at the practice needs to read it; nobody but the owner should change it. That is how the copay price mistake happened."},{move:"Select Copy link and paste it into the Front Office General channel.",why:"The team gets one link to the one real file, read-only."}],result:"Everyone can read the procedures; only you and the people you choose can change them.",takeaway:"Start from the narrowest link and the lowest permission, and widen only if someone truly needs more."},{type:"callout",variant:"warning",text:"For anything that contains patient information: share only with the specific people who need it (People you choose), give view access unless editing is required, keep it in a location Lakeside approves, and never use an Anyone link."}]},{heading:"Knowledge check",blocks:[{type:"knowledge-check",question:"Which link setting works for whoever has the link, even people outside Lakeside?",options:["People you choose","People in your organization","People with existing access","Anyone"],correctIndex:3,explanation:"An Anyone link does not check who is opening it, so it can be forwarded to anyone. Never use it for patient information.",optionRationales:["This works only for the people you name.","This works only for people signed in to Lakeside accounts.","This works only for people who already had access.","Correct."]},{type:"knowledge-check",question:"Jen needs to read the copay quick reference but must not change it. What permission do you give her?",options:["Can edit","Can view","Owner","No permission; email her a copy"],correctIndex:1,explanation:"Can view lets her open and read the file without changing it.",optionRationales:["Can edit lets her change it.","Correct.","There is no reason to make her an owner.","An emailed copy goes out of date and spreads extra copies."]}]}],challenge:[{type:"paragraph",text:"Share three files with least access in the Challenge Lab below:"},{type:"list",ordered:!0,items:["Share “Front Desk Procedures.docx” with Omar Haddad and Jen Cole, using People you choose and Can view, and send it.","Copy a link to “Reminder Call Script.docx” that works only for people who already have access.","From the Billing Questions channel's Shared tab, share “Copay Quick Reference.pdf” with Jen Cole, view only, and send it.","In a Word document or on paper, explain in two or three sentences why you would never share a file with patient information using an Anyone link."]},{type:"callout",variant:"success",text:"Deliverable: Submit your Challenge Lab results page (print it or save it as a PDF) and your explanation to your instructor or course folder."}]},{slug:"co-authoring",title:"Co-Authoring: Edit Files Together in Teams",description:"Open Word, Excel, and PowerPoint files inside Teams, work on the same file at the same time as coworkers, use comments and @mentions to review, and open a file in the desktop app or browser when you need more tools.",objectives:["Open an Office file in Teams and recognize when others are editing it with you","Add a comment and @mention the person who should act on it","Open a file in the desktop app or in the browser","Explain why co-authoring one shared file beats emailing copies"],duration:"15 min",slides:j("co-authoring",["One file, many editors, no copies","Open a file in Teams","See who is editing with you","Comments and @mentions for review","Desktop app or browser when you need more","Co-authoring etiquette"]),sections:[{heading:"One file, many editors",blocks:[{type:"scenario",role:"You are the front office assistant at Lakeside Medical Associates.",text:"Maria shared the team copy of the front desk procedures in the General channel and asked everyone to review step 3. Last year the same review happened by email: five people sent back five edited copies, and it took Maria an afternoon to combine them.",task:"Review the document in the one shared copy, with your coworkers, and leave clear comments instead of a sixth copy."},{type:"paragraph",text:"Co-authoring means several people work in the same Word, Excel, or PowerPoint file at the same time. When a file is stored in OneDrive or a team's SharePoint site and shared with you, you can open it and edit it while others do. You see their pictures or initials at the top of the file and their changes as they make them. There is only one file, so there is nothing to combine afterward."},{type:"list",items:["Select a file on a channel's or chat's Shared tab, in the message where it was attached, or in OneDrive. By default it opens inside Teams with the usual Office tools at the top.","Select Close to go back to where you were in Teams.","To work in the full app, open the file's Open menu and choose Desktop app or Open in browser. On the Shared tab you can also right-click the file and choose Open in. You can change the default for all files in Settings › Files and links."]}]},{heading:"Review with comments",blocks:[{type:"paragraph",text:"A comment is a note attached to the document, not a change to its text. Use comments to ask a question or suggest something the owner should decide. Type @ and a name in a comment to notify that person. The comment stays with the document, so everyone reviewing sees it in one place."},{type:"worked-example",title:"Reviewing step 3",task:"Check step 3 of the team procedures against the new copay rule.",steps:[{move:"Open Front Desk Procedures - Team.docx from the General channel's Shared tab.",why:"Opening the shared file, not a downloaded copy, means everyone sees the same document."},{move:"Notice Maria's and Omar's initials at the top of the file.",why:"They are editing too. Avoid rewriting the paragraph someone else is working on right now."},{move:"Open Comments and add: “@Maria Santos Step 3 now matches the new copay rule.”",why:"Maria owns the document. The @mention notifies her, and the comment stays with step 3."},{move:"Reply to Maria's post: “Reviewed. I left a comment on step 3.”",why:"The rest of the team can see the review is done without opening the file."}],result:"One document with everyone's input, and no copies to combine.",takeaway:"Edit the shared file, use comments for questions, and @mention the person who decides."},{type:"drag-drop",mode:"order",title:"Put the review in order",prompt:"Drag these steps into the order you would do them.",items:[{id:"1",text:"Open the file from the channel's Shared tab"},{id:"2",text:"Check who else is editing"},{id:"3",text:"Add a comment and @mention the owner"},{id:"4",text:"Close the file"},{id:"5",text:"Reply to the post to say the review is done"}],explanation:"Open the shared copy, be aware of others, comment where it matters, and close the loop in the channel."}]},{heading:"Co-authoring etiquette",blocks:[{type:"table",caption:"Working in a shared file",columns:["Do","Don't"],rows:[["Edit the shared copy","Download it, edit, and upload a second copy"],["Use comments for questions and suggestions","Rewrite someone else's section without asking"],["@mention the person who must decide","Leave a comment nobody is notified about"],["Close the file when you are done","Leave it open for days on a shared computer"]]}]},{heading:"Knowledge check",blocks:[{type:"knowledge-check",question:"You open the team procedures and see Maria's and Omar's initials at the top. What does that mean?",options:["They are editing the same file right now","They deleted the file","You opened a copy","The file is locked"],correctIndex:0,explanation:"Co-authoring shows the people working in the file with you.",optionRationales:["Correct.","A deleted file would not open.","Copies do not show other editors.","Co-authored files are not locked; everyone can edit."]},{type:"knowledge-check",question:"You have a question about step 5 for Omar. What is the best way to ask it?",options:["Rewrite step 5 the way you think it should be","Add a comment on the document with @Omar Haddad","Download a copy and email it with your question","Post the question in Staff Events"],correctIndex:1,explanation:"A comment with an @mention notifies Omar and keeps the question with the text it is about.",optionRationales:["Changing someone else's work without asking causes confusion.","Correct.","A downloaded copy splits the document.","Staff Events is for events, and the question belongs with the document."]}]}],challenge:[{type:"paragraph",text:"Review a shared document in the Challenge Lab below:"},{type:"list",ordered:!0,items:["Open “Front Desk Procedures - Team.docx” from the General channel's Shared tab.","Add a comment for Omar: “@Omar Haddad Step 5 looks good. Should we add the voicemail script too?”","Close the file and reply to Maria's post: “Done. I left a question for Omar about step 5.”","Copy a link to the file."]},{type:"callout",variant:"success",text:"Deliverable: Submit your Challenge Lab results page (print it or save it as a PDF) to your instructor or course folder."}]}],l=(a,b)=>b.map((b,c)=>({src:`/images/ms-office/teams/module-5/${a}/slide-${String(c+1).padStart(2,"0")}.jpg`,alt:b})),m=[{slug:"schedule-meetings",title:"Schedule and Answer Meetings",description:"Schedule Teams meetings from the Teams calendar, from a chat, and in a channel, know how Outlook fits in, answer invitations, and join by link, from your calendar, or with a meeting ID.",objectives:["Schedule a meeting with New event: title, required and optional attendees, date and time, repeat, and an agenda","Schedule a meeting from a chat and a channel meeting from a channel","Explain how Teams meetings scheduled in Outlook appear in Teams","Accept or decline invitations, and join from the calendar, a chat, or Join with an ID"],duration:"18 min",videoUrl:"https://www.youtube.com/embed/7yorEAIxu40",slides:l("schedule-meetings",["Meetings start with a clear invitation","Calendar › New event","Schedule from a chat, or in a channel","Teams meetings from Outlook","Accept, Tentative, or Decline","Ways to join: calendar, chat, link, or meeting ID"]),sections:[{heading:"A good invitation does half the work",blocks:[{type:"scenario",role:"You are the front office assistant at Lakeside Medical Associates.",text:"Maria asks you to set up a planning meeting for Saturday's flu clinic. Last time, the invitation said only “Flu stuff,” two people came without the supply counts, and the meeting ran 40 minutes over.",task:"Schedule meetings with a clear title, the right people, the right time, and an agenda, and answer the invitations you receive."},{type:"paragraph",text:"Teams calendar is the same calendar as your work Outlook calendar, so a meeting you schedule in either one appears in both. The current Teams calendar is the one Microsoft shares with the new Outlook; it is on by default, and the top-right toggle can switch back to the classic calendar if your organization still allows it."},{type:"list",ordered:!0,items:["Select Calendar on the app bar, then New event (or select an open time slot).","Add a title that says what the meeting is for.","Invite required attendees. To invite someone as optional, open Response options and add optional attendees.","Choose the date, start time, and end time. Set Repeat if the meeting happens every week or month. Check the Scheduling Assistant to see when people are free.","Make sure Teams meeting is turned on, add an agenda in the details, and select Send. (With no attendees, you Save it to your own calendar.)"]}]},{heading:"Schedule from a chat, a channel, or Outlook",blocks:[{type:"table",caption:"Other places to schedule a Teams meeting",columns:["From","How","Who is invited"],rows:[["A chat","More chat options (…) › Schedule a meeting","The people in the chat are filled in"],["A channel","The arrow next to Meet now › Schedule a meeting","Everyone on the team gets an invitation, and the meeting appears in the channel"],["New Outlook or Outlook on the web","New event, then turn on Teams meeting before Send","The people you invite"],["Classic Outlook","New Teams Meeting in the Calendar","The people you invite"]]},{type:"callout",variant:"info",text:"Channel meetings are good for team-wide meetings: everyone on the team can see the meeting in the channel and join. Channel meetings are not available in private channels. The Outlook course in this program covers scheduling from Outlook in detail."},{type:"worked-example",title:"Scheduling the flu clinic planning meeting",task:"Get the right people together for 30 minutes with a clear agenda.",steps:[{move:"Calendar › New event. Title: “Flu Clinic Planning.”",why:"The title tells people what the meeting is for before they open it."},{move:"Required: Maria Santos and Tasha Greene. Optional: Omar Haddad.",why:"Maria and Tasha must decide; Omar can come if he is free. Marking him optional tells him so."},{move:"Thursday, 2:00 PM to 2:30 PM, after checking the Scheduling Assistant.",why:"Picking a time when everyone is free saves a round of reschedules."},{move:"Details: “1. Supplies 2. Volunteers 3. Signage.” Then Send.",why:"An agenda lets people bring what is needed and keeps the meeting to 30 minutes."}],result:"An invitation people can prepare for, on everyone's Teams and Outlook calendar.",takeaway:"Clear title, the right people, a realistic time, and an agenda."}]},{heading:"Answer invitations and join",blocks:[{type:"paragraph",text:"Select a meeting on your calendar to see its details. Choose Accept, Tentative, or Decline so the organizer knows who is coming. When two meetings overlap, decide which one you will attend and decline the other, so nobody waits for you."},{type:"table",caption:"Ways to join a Teams meeting",columns:["From","Do this"],rows:[["Your calendar","Select the meeting › Join"],["The meeting chat","Open the meeting's chat › Join (while the meeting is going on)"],["An invitation link","Select the meeting link in the invite"],["A meeting ID","Calendar › the arrow next to Meet now › Join with an ID; type the ID and passcode"]]},{type:"drag-drop",mode:"match",title:"Where would you schedule it?",prompt:"Drag the best way to schedule each meeting.",items:[{id:"a",text:"A monthly review the whole Front Office team should see",match:"Channel meeting from Scheduling"},{id:"b",text:"A quick talk with the three people already in a group chat",match:"Schedule a meeting from the chat"},{id:"c",text:"A planning meeting with two required and one optional person",match:"Calendar › New event"},{id:"d",text:"A partner office gave you a meeting ID and passcode",match:"Join with an ID"}],explanation:"Start from where the people already are: a chat for its members, a channel for the team, the calendar for a custom list, and Join with an ID when all you have is an ID."}]},{heading:"Knowledge check",blocks:[{type:"knowledge-check",question:"You want Omar invited to a meeting, but he does not have to attend. What should you do?",options:["Leave him off the invitation","Add him as an optional attendee under Response options","Add him as required and tell him to ignore it","Forward him the meeting chat"],correctIndex:1,explanation:"Optional attendees get the invitation and know their attendance is not required.",optionRationales:["Then he would not know about the meeting.","Correct.","Required tells him he must attend.","The meeting chat is not an invitation."]},{type:"knowledge-check",question:"A partner office gives you only a meeting ID and passcode. How do you join?",options:["Start a new chat with the ID","Calendar › arrow next to Meet now › Join with an ID","Search for the ID in Activity","Create a New event with the ID as the title"],correctIndex:1,explanation:"Join with an ID asks for the meeting ID and passcode and takes you to the pre-join screen.",optionRationales:["A chat cannot join a meeting by ID.","Correct.","Activity lists notifications.","That would schedule a new meeting."]}]}],challenge:[{type:"paragraph",text:"Set up next week's meetings in the Challenge Lab below:"},{type:"list",ordered:!0,items:["Schedule “Patient Portal Training” with Jen Cole and Omar Haddad on Friday, October 23, 2026, from 10:00 AM to 10:45 AM, with the details “Bring your login.” Send it.","From your chat with Maria Santos, schedule “Weekly Check-in” on Monday, October 26, 2026, from 3:00 PM to 3:15 PM, repeating weekly.","Accept “Privacy Training Refresher.”","Decline “Vendor demo: Phone headsets.”","Join the meeting with ID 245 381 907 6 and passcode Lk7x2P, then select Join now."]},{type:"callout",variant:"info",text:"The dates in the Challenge Lab are part of the practice scenario, not due dates for you."},{type:"callout",variant:"success",text:"Deliverable: Submit your Challenge Lab results page (print it or save it as a PDF) to your instructor or course folder."}]},{slug:"join-and-participate",title:"Join a Meeting and Take Part",description:"Set up your camera, microphone, and background on the pre-join screen, use the meeting controls (Mic, Camera, Chat, Raise, React, Share, Leave), share a single window safely, and follow meeting etiquette.",objectives:["Use the pre-join screen to set your camera, microphone, and background before you join","Use the meeting controls: Mic, Camera, Chat, People, Raise, React, View, Notes, and Leave","Share a single window instead of your whole screen, and stop sharing","Follow meeting etiquette, including keeping patient information off a shared screen"],duration:"18 min",videoUrl:"https://www.youtube.com/embed/OEXshseuW0s",slides:l("join-and-participate",["Join ready: camera, microphone, background","The pre-join screen","Meeting controls you will use every time","Raise, React, and the meeting chat","Share a window, not your whole screen","Meeting etiquette"]),sections:[{heading:"Before you join: the pre-join screen",blocks:[{type:"scenario",role:"You are the front office assistant at Lakeside Medical Associates.",text:"The Front Office Huddle starts in one minute. You are at the check-in desk with patients in the background, a phone ringing, and the November schedule open on your screen next to the EHR. Last week someone joined unmuted and the whole huddle heard a patient give their date of birth at the window.",task:"Join the meeting ready: the right camera and microphone settings, a blurred background, and only the right window shared."},{type:"paragraph",text:"When you select Join, Teams shows the pre-join screen first. It shows your camera preview and lets you turn your camera and microphone on or off before anyone sees or hears you. Select Effects and avatars to blur your background or choose a background image. If you are in a meeting room with Teams equipment, Teams may suggest Room audio. When everything is set, select Join now."},{type:"callout",variant:"info",text:"Change your background during a meeting with More actions (…) › Video effects and settings: choose an effect, select Preview to check it, then Apply."}]},{heading:"Meeting controls",blocks:[{type:"table",caption:"Controls at the top of the meeting window",columns:["Control","What it does","Shortcut (Windows)"],rows:[["Mic","Mute or unmute yourself","Ctrl+Shift+M"],["Camera","Turn your video on or off","Ctrl+Shift+O"],["Share","Share your screen, a window, a PowerPoint file, or a whiteboard","Ctrl+Shift+E opens the share tray"],["Chat","Open the meeting chat",""],["People","See who is here and who is waiting",""],["Raise","Raise or lower your hand","Ctrl+Shift+K"],["React","Send a quick reaction (also has Raise hand)",""],["View","Change how people appear, such as Gallery or Large gallery",""],["Notes","Open shared meeting notes",""],["More (…)","Recording, captions, video effects, and more",""],["Leave","Leave the meeting (organizers can also End meeting)","Ctrl+Shift+H"]]},{type:"callout",variant:"version",text:"Together mode was retired in June 2026 and no longer appears under View. Gallery is the main layout. Organizers and presenters can still Spotlight someone's video for everyone, and anyone can Pin a video for themselves."},{type:"drag-drop",mode:"match",title:"Which control?",prompt:"Drag each meeting control onto the job it does.",items:[{id:"a",text:"Raise",match:"Ask to speak without interrupting"},{id:"b",text:"Mic",match:"Stop the room's noise from reaching everyone"},{id:"c",text:"Chat",match:"Post a link or a question others can read"},{id:"d",text:"Share",match:"Show one window to the meeting"},{id:"e",text:"People",match:"See who is in the meeting and who is waiting"}],explanation:"Each control has one job. Learning them means you never interrupt to ask how to do something."}]},{heading:"Share safely",blocks:[{type:"paragraph",text:"Select Share and choose what to show. Sharing your whole screen shows everything on it, including pop-up notifications and any other window you click by mistake. Sharing a single window shows only that program. At a medical office, share the specific window you need, close or minimize anything with patient information first, and select Stop sharing as soon as you are done. Teams turns on Do not disturb while you present, so chat pop-ups do not appear for everyone."},{type:"worked-example",title:"Showing the November schedule in the huddle",task:"Maria asks you to show the schedule while the EHR is also open on your screen.",steps:[{move:"Select Share, and under Window choose Provider Schedule - November.xlsx - Excel.",why:"Only the schedule is visible. The EHR window stays private even if you click on it."},{move:"Talk through the schedule.",why:"Everyone sees the same thing, so there is no confusion about which day you mean."},{move:"Select Stop sharing at the top of the window.",why:"Ending the share right away means nothing else appears by accident."}],result:"The team sees the schedule and nothing else.",takeaway:"Share a window, not your whole screen, and stop sharing the moment you are done."},{type:"table",caption:"Meeting etiquette at Lakeside",columns:["Do","Don't"],rows:[["Join on time and muted","Join unmuted from a busy front desk"],["Blur or choose a background in patient areas","Show patients or screens behind you"],["Raise your hand to speak","Talk over the presenter"],["Use the meeting chat for links and questions","Paste patient details into the meeting chat"],["Share one window, then stop sharing","Share your whole screen with the EHR open"]]}]},{heading:"Knowledge check",blocks:[{type:"knowledge-check",question:"Which shortcut mutes and unmutes your microphone in a Teams meeting on Windows?",options:["Ctrl+Shift+M","Ctrl+M","Ctrl+Shift+K","Alt+M"],correctIndex:0,explanation:"Ctrl+Shift+M toggles mute. Ctrl+Shift+K raises or lowers your hand.",optionRationales:["Correct.","That is not the Teams mute shortcut.","Ctrl+Shift+K raises or lowers your hand.","That is not the Teams mute shortcut."]},{type:"knowledge-check",question:"You need to show the schedule in a meeting, and the EHR is open on your screen. What should you share?",options:["Your entire screen","Only the schedule's window","Nothing; read it out loud","A photo of your screen"],correctIndex:1,explanation:"Sharing one window keeps everything else, including patient information, off the meeting.",optionRationales:["Your whole screen would show the EHR and any pop-ups.","Correct.","Sharing the schedule is fine when you share only its window.","A photo could still capture patient information."]}]}],challenge:[{type:"paragraph",text:"Attend Renee's privacy training in the Challenge Lab below:"},{type:"list",ordered:!0,items:["From the meeting chat “Privacy Training Refresher,” open the meeting's pre-join screen.","Turn off your camera and your microphone.","Join the meeting.","Turn on live captions.","Post your question in the meeting chat: “Does this training cover texting appointment reminders?”","Raise your hand.","Lower your hand, then leave the meeting."]},{type:"callout",variant:"success",text:"Deliverable: Submit your Challenge Lab results page (print it or save it as a PDF) to your instructor or course folder."}]},{slug:"host-a-meeting",title:"Host a Meeting: Lobby, Roles, and Recording",description:"Run a meeting you organize: admit people from the lobby, set presenter and attendee roles, mute participants, record and transcribe with notice, use breakout rooms, and end the meeting for everyone.",objectives:["Admit or deny people waiting in the lobby, and explain who can bypass the lobby","Explain the organizer, co-organizer, presenter, and attendee roles and change a role during a meeting","Mute participants, start and stop recording or transcription with notice, and end the meeting","Describe what breakout rooms are for and who can manage them"],duration:"20 min",videoUrl:"https://www.youtube.com/embed/fGvVREwX33E",slides:l("host-a-meeting",["Hosting is a job: start, steer, and end the meeting","The lobby: who gets in, and when","Meeting roles","Mute, record, and transcribe with notice","Breakout rooms","End the meeting for everyone"]),sections:[{heading:"The organizer's job",blocks:[{type:"scenario",role:"You are the front office assistant at Lakeside Medical Associates.",text:"You organize today's Front Desk Coverage Review. Dana Brooks from Riverside Imaging, an outside partner, is joining to explain their referral process, Omar is presenting the schedule, and Maria wants it recorded for the evening staff. Last month someone else's review ran 20 minutes over and a vendor sat in the lobby the whole time because nobody noticed.",task:"Use the host controls so the right people get in, the right people present, everyone knows about the recording, and the meeting ends on time."},{type:"paragraph",text:"The lobby is a waiting area. Depending on the meeting's options, some people join directly and others wait in the lobby until someone admits them. Organizers, co-organizers, and presenters can admit people by default. When someone is waiting, a banner appears with Admit and View lobby; in People, under Waiting in the lobby, select the check mark to admit someone or the X to deny them. Admit all admits everyone waiting."},{type:"paragraph",text:"Before the meeting, the organizer sets who can bypass the lobby in the meeting's options (Calendar › the meeting › View event › Options › Meeting access). Choices range from Only organizers and co-organizers to Everyone. For a meeting with outside partners, keeping guests in the lobby until you admit them is a sensible default."}]},{heading:"Roles",blocks:[{type:"table",caption:"What each role can do (from Microsoft's roles table)",columns:["Can","Organizer and co-organizer","Presenter","Attendee"],rows:[["Speak, share video, chat","Yes","Yes","Yes"],["Share content","Yes","Yes","No"],["Mute others, admit from lobby, change roles","Yes","Yes","No"],["Start or stop recording and transcription","Yes","Yes","No"],["Manage breakout rooms, change meeting options","Yes","No","No"]]},{type:"paragraph",text:"To change someone's role during a meeting, select People, point to their name, select More options (…), and choose Make a presenter or Make an attendee. A role change made this way applies to this meeting only. For a meeting with outside guests, make guests attendees so they can listen and talk but not share their screen or remove people."},{type:"drag-drop",mode:"match",title:"Which role fits?",prompt:"Drag the role that fits each person in the coverage review.",items:[{id:"a",text:"Omar, who will share the schedule",match:"Presenter"},{id:"b",text:"Dana, an outside partner who will only talk",match:"Attendee"},{id:"c",text:"Maria, who should be able to change meeting options with you",match:"Co-organizer"},{id:"d",text:"You, who scheduled the meeting",match:"Organizer"}],explanation:"Give each person the least access they need to do their part in the meeting."}]},{heading:"Recording, transcription, and breakout rooms",blocks:[{type:"list",ordered:!0,items:["Tell people first. A short note in the meeting chat (“This meeting will be recorded for staff who can't attend”) is a good habit.","Select More (…) › Record. Check the spoken language and what to record (audio and video, or audio only), then select Confirm. Everyone in the meeting is notified that recording has started, and live transcription starts with it.","To stop, select More (…) › Recording; this stops the recording and the transcript. Selecting Transcribing stops only the transcript and keeps recording. To get a transcript without a recording, select More (…) › Transcribe › Confirm.","The recording is saved in the organizer's OneDrive for work or school (or SharePoint for a channel meeting) and a link appears in the meeting chat. Your organization may set recordings to expire after a period of time."]},{type:"callout",variant:"warning",text:"Only record when you have a business reason and people know about it. At Lakeside, do not record meetings where patient information will be discussed unless the practice has approved it, and never record a meeting with outside partners without telling them first."},{type:"paragraph",text:"Breakout rooms split a meeting into smaller groups and bring everyone back afterward. The organizer, or a presenter the organizer appoints as breakout rooms manager, creates them with Rooms in the meeting controls (or More › Rooms), assigns people manually, randomly, or by letting them choose, then selects Open rooms. Close rooms brings everyone back to the main meeting."},{type:"worked-example",title:"Running the coverage review",task:"Start on time, admit the partner, record with notice, and end on time.",steps:[{move:"Join, then Admit Dana Brooks from the lobby banner.",why:"An outside guest waits in the lobby; admitting her right away keeps the meeting on time."},{move:"People › Omar Haddad › More options › Make a presenter. Leave Dana as an attendee.",why:"Omar needs to share the schedule. Dana only needs to talk."},{move:"People › Mute all.",why:"Several people are in noisy areas; muting everyone keeps the audio clean. People can unmute to speak."},{move:"Post the recording notice in the meeting chat, then More › Record › Confirm.",why:"People know before it starts, and Teams notifies everyone too."},{move:"At the end, More › Recording to stop the recording, then the arrow next to Leave › End meeting.",why:"End meeting closes it for everyone, so nobody stays in an empty meeting."}],result:"A meeting that started and ended on time, with a recording everyone knew about.",takeaway:"Admit promptly, give the least role needed, announce before recording, and end the meeting for everyone."}]},{heading:"Knowledge check",blocks:[{type:"knowledge-check",question:"Which role can share content but cannot manage breakout rooms or change meeting options?",options:["Organizer","Co-organizer","Presenter","Attendee"],correctIndex:2,explanation:"Presenters have most controls, including sharing, but managing breakout rooms and meeting options is for organizers and co-organizers.",optionRationales:["Organizers can do both.","Co-organizers have the same capabilities as the organizer.","Correct.","Attendees cannot share content."]},{type:"knowledge-check",question:"What should you do before you start recording a meeting?",options:["Nothing; Teams handles it","Tell participants, and make sure there is a business reason and approval if patient information may come up","Turn off everyone's camera","Make everyone an attendee"],correctIndex:1,explanation:"Teams notifies everyone when recording starts, but telling people first and having a reason (and approval for anything involving patient information) is part of doing it professionally.",optionRationales:["Teams notifies people, but you are still responsible for having a reason and giving notice.","Correct.","Cameras have nothing to do with consent to record.","Roles do not replace notice."]}]}],challenge:[{type:"paragraph",text:"Run the Patient Experience Committee meeting in the Challenge Lab below:"},{type:"list",ordered:!0,items:["Join “Patient Experience Committee,” the meeting you organize.","Admit Jen Cole from the lobby.","Mute all participants.","Start transcription (without recording).","In meeting Notes, add the note “Omar drafts a running-late text message.”","Stop transcription and end the meeting for everyone."]},{type:"callout",variant:"success",text:"Deliverable: Submit your Challenge Lab results page (print it or save it as a PDF) to your instructor or course folder."}]},{slug:"captions-recordings-and-follow-up",title:"Captions, Transcripts, Recordings, and Follow-Up",description:"Use live captions, understand the difference between captions, transcripts, and recordings, find a meeting's recording and notes afterward, and send a follow-up that turns a meeting into action.",objectives:["Turn live captions on and off, and explain that captions are not saved","Explain the difference between live captions, a transcript, and a recording","Find a meeting's recording and notes in the meeting chat after it ends","Post a follow-up with clear action items in the meeting chat"],duration:"15 min",slides:l("captions-recordings-and-follow-up",["Captions, transcripts, and recordings","Turn on live captions","Captions vs. transcript vs. recording","Meeting notes everyone can see","After the meeting: the meeting chat","A follow-up that turns talk into action"]),sections:[{heading:"Captions help everyone follow along",blocks:[{type:"scenario",role:"You are the front office assistant at Lakeside Medical Associates.",text:"You missed the second half of yesterday's Billing Workflow Check-in to help a patient at the window. Today's huddle is in the middle of the noisy front office, where you can barely hear Maria through your earbuds. By Friday, nobody will remember who agreed to cover what.",task:"Use captions to follow along, catch up from a recording, and send a follow-up that records the decisions."},{type:"paragraph",text:"Live captions show what people say as text on your screen during a meeting. Turning captions on changes only your own screen. To turn them on, select More (…) › Captions. To turn them off, select More (…) › Captions again. Teams does not save captions; if you need a record, turn on transcription."},{type:"table",caption:"Captions, transcripts, and recordings",columns:["","Live captions","Transcript","Recording"],rows:[["What it is","Text of what people say, on your screen","A saved written record of the meeting","Saved video and audio of the meeting"],["Saved afterward?","No","Yes","Yes"],["Who turns it on","Anyone, for themselves","Organizer or presenter","Organizer or presenter"],["Others notified?","No","Yes","Yes"]]}]},{heading:"Notes and the meeting chat",blocks:[{type:"paragraph",text:"Select Notes in the meeting controls to open shared meeting notes that people in the meeting can see and add to. Notes are a good place for decisions and action items as they happen. Every Teams meeting also has a meeting chat. It is available before, during, and after the meeting: messages posted during the meeting stay there, and when a meeting is recorded, a link to the recording appears in the meeting chat (or in the channel conversation for a channel meeting)."},{type:"worked-example",title:"Following up on the huddle",task:"Make sure Friday's coverage decisions do not get lost.",steps:[{move:"During the huddle, turn on live captions and add “Alex covers check-in 12:00 to 1:00 on Friday” in Notes.",why:"Captions help in a noisy room, and the note captures the decision at the moment it is made."},{move:"After you leave, open the Front Office Huddle meeting chat.",why:"Everyone who was invited can see the meeting chat, so it is the natural place for the follow-up."},{move:"Post “Action items:” with a bulleted list of who does what.",why:"A short list with names makes each person's task clear and easy to find later."}],result:"Everyone has the decisions in writing, in the place they look for this meeting.",takeaway:"Capture decisions during the meeting, then post action items with names in the meeting chat."},{type:"drag-drop",mode:"order",title:"Put the meeting in order",prompt:"Drag these steps into the order they happen.",items:[{id:"1",text:"Send an invitation with an agenda"},{id:"2",text:"Join from the pre-join screen with the right settings"},{id:"3",text:"Capture decisions in Notes during the meeting"},{id:"4",text:"Leave or end the meeting"},{id:"5",text:"Post action items in the meeting chat"}],explanation:"A good meeting has a clear start (agenda), clear decisions during, and a clear finish (action items)."},{type:"callout",variant:"info",text:"Some organizations also have AI meeting features. AI-generated recaps (intelligent recap, such as AI meeting notes and recommended tasks) need a Teams Premium or Microsoft 365 Copilot license, and Copilot in Teams meetings needs a Microsoft 365 Copilot license, so you may not see them at work. Notes and a written follow-up work everywhere."}]},{heading:"Knowledge check",blocks:[{type:"knowledge-check",question:"You turned on live captions during a meeting. What happens after the meeting ends?",options:["The captions are saved as a transcript","Teams does not save captions","The captions are emailed to everyone","The captions become the meeting notes"],correctIndex:1,explanation:"Captions appear only during the meeting. For a saved record, the organizer or a presenter turns on transcription.",optionRationales:["Captions and transcripts are different; captions are not saved.","Correct.","Teams does not email captions.","Notes are separate and typed by people."]},{type:"knowledge-check",question:"Where do you usually find the recording of a meeting you were invited to?",options:["In the meeting chat","In your Recycle bin","In Settings","In the Apps page"],correctIndex:0,explanation:"A link to the recording appears in the meeting chat (or the channel conversation for a channel meeting).",optionRationales:["Correct.","The Recycle bin holds deleted files.","Settings holds preferences.","Apps lists apps you can add."]}]}],challenge:[{type:"paragraph",text:"Catch up and follow up in the Challenge Lab below:"},{type:"list",ordered:!0,items:["Open the recording in the Billing Workflow Check-in meeting chat.","Close it and react to Kevin's message with a Like.","Join the Front Office Huddle and turn on live captions.","Add a note: “Tasha restocks Room 3 before 2:00 PM.”","Leave, then post in the Front Office Huddle meeting chat: “Notes are in the meeting. Tasha restocks Room 3 before 2:00 PM.”"]},{type:"callout",variant:"success",text:"Deliverable: Submit your Challenge Lab results page (print it or save it as a PDF) to your instructor or course folder."}]}],n=(a,b)=>b.map((b,c)=>({src:`/images/ms-office/teams/module-6/${a}/slide-${String(c+1).padStart(2,"0")}.jpg`,alt:b})),o=[{moduleNumber:1,moduleSlug:"module-1",title:"Getting Started with Teams",emoji:"\uD83D\uDCAC",description:"What Teams is for, the parts of the window, your status, and notifications that work for you instead of against you.",lessons:e,level:"Beginner",estimatedMinutes:60},{moduleNumber:2,moduleSlug:"module-2",title:"Chat",emoji:"\uD83D\uDDE8️",description:"One-on-one and group chats, clear messages with formatting and @mentions, reactions and replies, and sharing files safely.",lessons:g,level:"Beginner",estimatedMinutes:70},{moduleNumber:3,moduleSlug:"module-3",title:"Teams and Channels",emoji:"\uD83D\uDC65",description:"Join a team, post and reply in channels, make announcements, set channel notifications, and use the Shared tab and channel tabs.",lessons:i,level:"Beginner",estimatedMinutes:50},{moduleNumber:4,moduleSlug:"module-4",title:"Files and Collaboration",emoji:"\uD83D\uDCC1",description:"Where Teams stores files, sharing with the right people and permissions, and co-authoring one shared file with comments.",lessons:k,level:"Intermediate",estimatedMinutes:50},{moduleNumber:5,moduleSlug:"module-5",title:"Meetings",emoji:"\uD83C\uDFA5",description:"Schedule and answer meetings, join ready, take part professionally, host with the lobby and roles, and follow up with captions, notes, and recordings.",lessons:m,level:"Intermediate",estimatedMinutes:75},{moduleNumber:6,moduleSlug:"module-6",title:"Working Smarter in Teams",emoji:"\uD83E\uDDF0",description:"Quick calls, apps like Planner and Approvals, Loop components everyone can edit, Copilot basics, accessibility tools, and Teams on your phone.",lessons:[{slug:"calls",title:"Calls in Teams",description:"Make audio and video calls to coworkers from a chat or the Calls app, use the call controls, know when a call beats a message, and understand what calling phone numbers requires.",objectives:["Start an audio or video call from a chat, or call someone from the Calls app","Use the call controls: Mic, Camera, Share, and Leave, with their shortcuts","Decide when a quick call works better than a chat, and follow up in writing","Explain that calls between Teams users at work are built in, while calling phone numbers needs Teams Phone"],duration:"12 min",slides:n("calls",["A quick call can save ten messages","Call from a chat: Video call or Audio call","The Calls app","Call controls and shortcuts","Teams calls and phone numbers","Call, then confirm in writing"]),sections:[{heading:"When a call beats a chat",blocks:[{type:"scenario",role:"You are the front office assistant at Lakeside Medical Associates.",text:"The check-in label printer is jammed again. You and Luis in IT have traded nine chat messages (“Is the light blinking?” “Which light?”) while patients wait in line. A two-minute call would have fixed it.",task:"Know when to call instead of typing, place the call quickly, and confirm what you agreed in writing afterward."},{type:"paragraph",text:"Teams calls are one-on-one or small-group audio or video conversations that you start right away, without scheduling a meeting. They work best for something urgent, something easier to show than to describe, or a back-and-forth that is going nowhere in chat. If the person's status is Busy or Do not disturb and it is not urgent, send a message instead."},{type:"list",ordered:!0,items:["From a chat: open the chat and select Video call or Audio call at the top right. To call several people, start a group chat with them first (calls from a chat work for up to 20 people).","From the Calls app: select Calls on the app bar, type a name in the box, and select the person to call. You can also call from someone's profile card.","To answer an incoming call, choose video or audio on the call notification (Ctrl+Shift+A accepts with video, Ctrl+Shift+S with audio)."]}]},{heading:"Call controls",blocks:[{type:"table",caption:"Call controls work like meeting controls",columns:["Control","Shortcut (Windows)","Use it to"],rows:[["Mic","Ctrl+Shift+M","Mute while the front desk is noisy"],["Camera","Ctrl+Shift+O","Turn on video to show something"],["Share","Ctrl+Shift+E","Show one window, such as an error message"],["Leave","Ctrl+Shift+H","Hang up"]]},{type:"callout",variant:"info",text:"Calls between Teams users in your organization are built into Teams. Calling regular phone numbers from Teams is different: your organization needs Teams Phone licenses and a phone service connected to Teams. If you see a dial pad in Calls, your organization has set that up for you."},{type:"worked-example",title:"Fixing the printer with one call",task:"Get the label printer working before the next patient reaches the window.",steps:[{move:"In Calls, type Luis and select Luis Ortega to call him.",why:"Showing and talking is faster than describing lights in a chat."},{move:"Mute while Luis checks the printer log on his end.",why:"Your microphone would pick up the waiting room. Mute until you need to talk."},{move:"When it works, unmute, thank him, and hang up with Leave.",why:"Short calls end when the problem is solved."},{move:"Send a chat: “Printer fixed: Luis cleared the jam and replaced the roller.”",why:"A written note tells anyone who checks later what happened. Calls leave no record unless you write one."}],result:"The printer works, and the fix is written down.",takeaway:"Call to solve, then write to confirm."},{type:"drag-drop",mode:"sort",title:"Call or message?",prompt:"Sort each situation.",buckets:[{id:"call",label:"Call"},{id:"msg",label:"Send a message"}],items:[{id:"a",text:"The printer is jammed and patients are waiting",bucket:"call"},{id:"b",text:"Asking Kevin to update a spreadsheet by Friday",bucket:"msg"},{id:"c",text:"Tasha needs to see the supply shelf to know what to order",bucket:"call"},{id:"d",text:"Maria is in Do not disturb and the question is not urgent",bucket:"msg"},{id:"e",text:"Nine messages in, and you still don't understand each other",bucket:"call"}],explanation:"Call when it is urgent, visual, or going in circles. Message when it can wait or needs a written record."}]},{heading:"Knowledge check",blocks:[{type:"knowledge-check",question:"Where do you start an audio call with someone you are already chatting with?",options:["Calendar › New event","Audio call at the top right of the chat","Settings › Devices","Activity"],correctIndex:1,explanation:"Every chat has Video call and Audio call at the top right.",optionRationales:["That schedules a meeting.","Correct.","Devices is for setting up audio and video.","Activity lists notifications."]},{type:"knowledge-check",question:"Which is true about calling phone numbers from Teams at work?",options:["Anyone can call any phone number for free","It needs Teams Phone licenses and a phone service your organization sets up","It only works on the mobile app","It is the same as a Teams-to-Teams call"],correctIndex:1,explanation:"Teams-to-Teams calls are built in. Calling regular phone numbers needs Teams Phone and a connected phone service.",optionRationales:["Phone calls need setup and licenses.","Correct.","It is not limited to mobile.","Phone calls go through a phone network; Teams-to-Teams calls do not."]}]}],challenge:[{type:"paragraph",text:"Make two calls and follow up in the Challenge Lab below:"},{type:"list",ordered:!0,items:["Start an audio call with Kevin Patel from your chat with him.","Mute yourself while Kevin looks up the copay rule, then hang up.","Send Kevin a written summary: “Confirmed: copays are collected at check-in.”","In Calls, call Omar Haddad.","Hang up."]},{type:"callout",variant:"success",text:"Deliverable: Submit your Challenge Lab results page (print it or save it as a PDF) to your instructor or course folder."}]},{slug:"apps-planner-and-approvals",title:"Apps in Teams: Planner, Approvals, and Copilot",description:"Add and pin apps, track team tasks with Planner, send approval requests with Approvals, know what Lists and Forms are for, and use Copilot in Teams responsibly if your organization provides it.",objectives:["Open an app from Apps and pin it to the app bar","Add, assign, and complete tasks in Planner (My Day, My Tasks, My Plans)","Send an approval request with the Approvals app","Describe what Copilot in Teams can do, what it requires, and how to use it responsibly"],duration:"18 min",videoUrl:"https://www.youtube.com/embed/KVYUPf3xETM",slides:n("apps-planner-and-approvals",["Apps bring your work into Teams","Find and pin apps","Planner: My Day, My Tasks, My Plans","Approvals: ask, approve, and keep a record","Lists, Forms, and channel tabs","Copilot in Teams: optional, and only with your organization's approval"]),sections:[{heading:"Apps bring your work into Teams",blocks:[{type:"scenario",role:"You are the front office assistant at Lakeside Medical Associates.",text:"The flu clinic is Saturday. Tasks live on sticky notes, in three chats, and in Maria's head. You also need Maria to approve a $38 replacement roller for the label printer, and last time the request got lost in her email.",task:"Use Planner to track who is doing what, and Approvals to make a request that cannot get lost."},{type:"paragraph",text:"Apps add tools to Teams. Select Apps on the app bar to browse, search for an app (such as Planner), and open or add it. An app you open appears on the app bar; to keep it there, right-click its icon and select Pin. Apps can also be added as tabs in channels and chats (Module 3). Your organization decides which apps are available."}]},{heading:"Planner",blocks:[{type:"paragraph",text:"Planner (called Tasks by Planner and To Do before 2024) collects your tasks in one place. My Day shows tasks due today and anything you add to it. My Tasks shows your private tasks, tasks assigned to you, and flagged emails. My Plans shows personal and shared plans. A shared plan can also be a Planner tab in a channel, so the whole team sees the same tasks."},{type:"list",ordered:!0,items:["Open Planner and go to My Tasks (or a plan).","Type the task name in Add new task.","Set a due date and assign it to the person who will do it.","Select the circle next to a task to mark it complete."]},{type:"worked-example",title:"Tracking the flu clinic tasks",task:"Turn sticky notes into tasks with an owner and a due date.",steps:[{move:"Add “Order flu clinic signage,” due Friday, assigned to yourself.",why:"A task with one owner and a date gets done; “someone should order signs” does not."},{move:"Add “Confirm volunteer list,” due Thursday, assigned to Tasha.",why:"Tasha sees it in her own Planner, so nobody has to remind her in chat."},{move:"Mark “Restock intake clipboards” complete.",why:"Checking it off tells Maria it is done without another message."}],result:"Everyone can see what is left, who owns it, and when it is due.",takeaway:"Every task gets one owner and a due date."}]},{heading:"Approvals, Lists, and Forms",blocks:[{type:"paragraph",text:"The Approvals app sends a request to one or more approvers and keeps a record of the request and the answer. Open Approvals, select New approval request, give it a clear name, add the approvers, add the details they need to decide (what, why, and how much), and select Send. You can see the status of requests you sent and received in the app. Approvals is available in Teams by default, but your organization can turn it off, and it runs on Power Automate behind the scenes."},{type:"table",caption:"Other apps you may see in Teams",columns:["App","Use it for","Lakeside example"],rows:[["Lists","Tracking information in rows and columns that a team updates","Supply requests or equipment issues"],["Forms","Surveys, quizzes, and sign-up forms","Staff lunch preferences or training sign-ups"],["Planner tab","A shared task plan in a channel","Front Office tasks in the Scheduling channel"]]},{type:"drag-drop",mode:"match",title:"Which app?",prompt:"Drag the app onto the job it fits.",items:[{id:"a",text:"Maria needs to OK a $38 purchase, with a record",match:"Approvals"},{id:"b",text:"Assign “Confirm volunteer list” to Tasha by Thursday",match:"Planner"},{id:"c",text:"Ask staff which training times work for them",match:"Forms"},{id:"d",text:"Track every broken piece of equipment and its status",match:"Lists"}],explanation:"Planner tracks tasks, Approvals records decisions, Forms collects answers, and Lists tracks items over time."}]},{heading:"Copilot in Teams (optional)",blocks:[{type:"paragraph",text:"Some organizations turn on Copilot, Microsoft's AI assistant, in Teams. When it is turned on, Copilot appears at the top of Chat, where you can ask it questions or ask it to draft a message. Using Copilot in your chats, meetings, and calls (for example, to summarize what was discussed in a meeting or list follow-up tasks) needs a Microsoft 365 Copilot license. AI meeting recaps (intelligent recap) need a Teams Premium or Microsoft 365 Copilot license. Your organization decides whether you see Copilot and which licenses you have, so you may not see these features at work."},{type:"callout",variant:"warning",text:"AI can be wrong. Check Copilot's answers and the sources it shows before you rely on them or send them to anyone. Use only the AI tools your organization approves, and never paste patient information into an AI tool unless Lakeside has approved that tool for patient information."}]},{heading:"Knowledge check",blocks:[{type:"knowledge-check",question:"You opened Planner from Apps and want it to stay on the app bar. What do you do?",options:["Nothing; apps always stay","Right-click Planner on the app bar and select Pin","Add it as a status message","Restart Teams"],correctIndex:1,explanation:"Pinning keeps an app on the app bar after you leave it.",optionRationales:["An app you open shows only while you use it unless you pin it.","Correct.","Status messages are about your availability.","Restarting does not pin apps."]},{type:"knowledge-check",question:"Which is the most responsible way to use Copilot in Teams at a medical office?",options:["Paste patient notes in to get a quick summary","Use it only if your organization provides it, check its answers, and keep patient information out unless the tool is approved for it","Send its drafts without reading them","Use a personal AI app instead when Copilot is not available"],correctIndex:1,explanation:"Approved tools, human review, and no patient information unless approved.",optionRationales:["Patient information goes only into tools the practice has approved for it.","Correct.","AI drafts can contain mistakes; read before you send.","Personal AI apps are not approved work tools."]}]}],challenge:[{type:"paragraph",text:"Track the work and get the approval in the Challenge Lab below:"},{type:"list",ordered:!0,items:["Pin Planner and Approvals to the app bar.","In Planner, add “Print flu clinic sign-in sheets,” due Friday, October 23, assigned to Omar Haddad.","Mark “Update the copay log” complete.","In Approvals, send Renee Walker a request named “Headset for check-in window 2” with the details “Jabra Evolve2 40 headset, $89.”"]},{type:"callout",variant:"info",text:"The dates in the Challenge Lab are part of the practice scenario, not due dates for you."},{type:"callout",variant:"success",text:"Deliverable: Submit your Challenge Lab results page (print it or save it as a PDF) to your instructor or course folder."}]},{slug:"loop-components",title:"Loop Components: Lists and Tables Everyone Can Edit",description:"Send a Loop component (a paragraph, checklist, or table) in a chat so everyone can edit the same content right in the conversation, and know where Loop components are stored and who can see them.",objectives:["Send a Loop component in a chat with the Loop components button","Add to a Loop component someone else sent","Explain that Loop components are saved in the creator's OneDrive and editable by everyone in the chat","Decide when a Loop component works better than a string of replies"],duration:"12 min",slides:n("loop-components",["One list everyone edits, right in the chat","Send a Loop component","Edit together: everyone sees changes instantly","Where Loop components live and who can see them","Loop component or regular message?","Quick check"]),sections:[{heading:"One list instead of twenty replies",blocks:[{type:"scenario",role:"You are the front office assistant at Lakeside Medical Associates.",text:"Last year the flu clinic supply list was built from 23 chat replies (“also gloves,” “we have gloves,” “need more bandages”), and two boxes of the wrong supplies were ordered. This year Maria sent the list as a Loop component.",task:"Add to a shared Loop list and send your own Loop components so a group works on one up-to-date list."},{type:"paragraph",text:"A Loop component is a small piece of content, such as a paragraph, a checklist, or a table, that you send in a chat. Everyone in the chat can edit it right in the conversation, and changes appear for everyone instantly. Instead of replying “add alcohol pads,” you add alcohol pads to the list."},{type:"list",ordered:!0,items:["Open the chat.","In the compose box, select Loop components (the Loop icon).","Choose a component type, such as Paragraph, Checklist, or Table.","Add a title or a short message and any first items, then select Send.","Others edit the component right in the chat. In a Loop component, typing / offers options such as @mentions and dates, and typing // adds a comment."]}]},{heading:"Where Loop components live",blocks:[{type:"paragraph",text:"A Loop component you send in chat is saved automatically as a .loop file in your OneDrive, and people in the chat can edit it. The file also shows up in OneDrive and the Loop app, where it opens in a browser. You need a OneDrive to create Loop components; without one, you may still be able to edit components others send, but you can't create your own."},{type:"callout",variant:"warning",text:"Treat a Loop component like any shared file: everyone in the chat can see and change it, and the link can be shared. Keep patient information out of Loop components in chats unless Lakeside has approved it."},{type:"drag-drop",mode:"sort",title:"Loop component or regular message?",prompt:"Sort each situation.",buckets:[{id:"loop",label:"Loop component"},{id:"msg",label:"Regular message"}],items:[{id:"a",text:"A supply list several people will add to",bucket:"loop"},{id:"b",text:"Telling Tasha the 10:30 patient is ready",bucket:"msg"},{id:"c",text:"A table of Friday's reschedule calls and who is calling each",bucket:"loop"},{id:"d",text:"Thanking Luis for fixing the printer",bucket:"msg"},{id:"e",text:"Collecting everyone's lunch order",bucket:"loop"}],explanation:"Use a Loop component when several people will add to or update the same content. Use a regular message for a one-time update."}]},{heading:"Knowledge check",blocks:[{type:"knowledge-check",question:"How do you send a Loop component in a Teams chat?",options:["Settings › Loop","Select Loop components in the compose box and pick a component type","Attach a Word file","Start a meeting"],correctIndex:1,explanation:"The Loop components button in the compose box lets you choose a paragraph, checklist, table, or other component.",optionRationales:["Loop is not a setting.","Correct.","A Word file is a separate document, not a Loop component.","Meetings are a different tool."]},{type:"knowledge-check",question:"Who can edit a Loop component you send in a group chat?",options:["Only you","Everyone in the chat","Only your manager","Nobody; it is read-only"],correctIndex:1,explanation:"Everyone in the chat can edit it inline, and the changes show for everyone.",optionRationales:["Loop components are made to be edited together.","Correct.","Everyone in the chat can edit, not just one person.","They are editable, not read-only."]}]}],challenge:[{type:"paragraph",text:"Work on one list together in the Challenge Lab below:"},{type:"list",ordered:!0,items:["Add “Ice packs” to Maria's flu clinic supplies checklist.","Reply to Maria's checklist message: “Added ice packs. Everything else is in the supply closet.”","In your chat with Tasha Greene, send a Checklist Loop component with the message “Room 2 restock list.”"]},{type:"callout",variant:"success",text:"Deliverable: Submit your Challenge Lab results page (print it or save it as a PDF) to your instructor or course folder."}]},{slug:"accessibility-and-mobile",title:"Accessibility and Teams on Your Phone",description:"Use the accessibility tools built into Teams (Immersive Reader, live captions, themes, zoom, keyboard shortcuts, and screen reader support), and use the Teams mobile app safely at work.",objectives:["Open a message in Immersive Reader and use its reading tools","Change the Teams theme and zoom level, and use keyboard shortcuts","Turn on live captions and set noise suppression so others can hear you","Use the Teams mobile app safely, keeping patient information private"],duration:"15 min",slides:n("accessibility-and-mobile",["Teams has accessibility tools built in","Immersive Reader","See it your way: theme and zoom","Hear and be heard: captions and noise suppression","Keyboard shortcuts and screen readers","Teams on your phone"]),sections:[{heading:"Accessibility tools are for everyone",blocks:[{type:"scenario",role:"You are the front office assistant at Lakeside Medical Associates.",text:"Renee posted a long list of new privacy steps for check-in. Omar, who has dyslexia, says long posts are hard to get through. The afternoon sun makes your screen hard to read, and the front desk is too loud to hear the huddle clearly.",task:"Use the tools built into Teams so everyone, including you, can read, hear, and take part."},{type:"table",caption:"Accessibility tools in Teams",columns:["Need","Tool","Where"],rows:[["Reading long text","Immersive Reader: read aloud, text size and spacing, line focus, translation","Point to a message › More options (…) › Immersive Reader"],["Seeing the screen","Theme (Follow operating system theme, Light, Dark) and high contrast","Settings and more (…) › Settings › Appearance and accessibility"],["Seeing the screen","Zoom in and out","Ctrl+= and Ctrl+-"],["Hearing meetings","Live captions","In a meeting: More (…) › Captions"],["Being heard","Noise suppression","Settings › Devices"],["Using the keyboard","Keyboard shortcuts","Ctrl+. shows them all"],["Using a screen reader","Support for Windows Narrator, JAWS, and NVDA","Works with Teams on Windows"]]},{type:"image",src:"/images/ms-office/teams/module-6/accessibility-and-mobile/infographic.png",alt:"Accessibility in Teams quick reference: Immersive Reader, theme and zoom, live captions and noise suppression, keyboard shortcuts and screen readers, and tips for posts that work for everyone",caption:"Accessibility in Teams quick reference"},{type:"paragraph",text:"Teams also has a Sign language mode for meetings with sign language interpreters. Your coworkers may use any of these tools. Writing clear posts with headings or numbered lists, and not relying on color alone, helps everyone who uses them."}]},{heading:"Use the tools",blocks:[{type:"worked-example",title:"Getting through Renee's privacy steps",task:"Read a long post comfortably and make sure you understood it.",steps:[{move:"Point to Renee's post › More options (…) › Immersive Reader.",why:"It opens the text full screen with larger, spaced-out text and can read it aloud."},{move:"Use the text size controls, and select Play to hear it read.",why:"Hearing and seeing the text together helps many readers, not only people with dyslexia."},{move:"Close Immersive Reader and reply to confirm what you changed at your desk.",why:"Replying shows Renee the steps were understood and done."}],result:"You read the full post and confirmed it in the thread.",takeaway:"Use the reading tools whenever text is long or hard to read, and write posts that work well with them."},{type:"drag-drop",mode:"match",title:"Match the need to the tool",prompt:"Drag the tool that helps each coworker.",items:[{id:"a",text:"Omar finds long posts hard to read",match:"Immersive Reader"},{id:"b",text:"Tasha can't hear the huddle over the waiting room",match:"Live captions"},{id:"c",text:"Screen glare makes text hard to see",match:"Theme or zoom"},{id:"d",text:"Kevin prefers not to use a mouse",match:"Keyboard shortcuts"},{id:"e",text:"The meeting can hear the front desk behind you",match:"Noise suppression"}],explanation:"Each tool solves a specific barrier. Knowing them lets you help coworkers, not just yourself."}]},{heading:"Teams on your phone",blocks:[{type:"paragraph",text:"The Teams mobile app for iPhone and Android uses the same work account, so your chats, channels, meetings, and files are the same as on your computer. It is handy for checking a schedule change or joining a meeting away from your desk. Your organization may require you to install it a certain way or may not allow work apps on personal phones; follow Lakeside's mobile device policy."},{type:"callout",variant:"warning",text:"A phone is easy to lose and easy for others to see. Lock your phone, do not open patient information in public places, and remember that notifications can show message previews on your lock screen."}]},{heading:"Knowledge check",blocks:[{type:"knowledge-check",question:"Where do you open Immersive Reader for a Teams message?",options:["Settings › Devices","Point to the message › More options (…) › Immersive Reader","Calendar","The Apps page"],correctIndex:1,explanation:"Immersive Reader opens from a message's More options menu.",optionRationales:["Devices is for audio and video.","Correct.","Calendar is for meetings.","Immersive Reader is not an app you add."]},{type:"knowledge-check",question:"Which shortcut shows all Teams keyboard shortcuts on Windows?",options:["Ctrl+E","Ctrl+. (period)","Ctrl+Shift+M","Ctrl+N"],correctIndex:1,explanation:"Ctrl+. (period) shows the keyboard shortcuts list.",optionRationales:["Ctrl+E goes to Search.","Correct.","Ctrl+Shift+M mutes in a meeting.","Ctrl+N starts a new chat."]}]}],challenge:[{type:"paragraph",text:"Try the accessibility tools in the Challenge Lab below:"},{type:"list",ordered:!0,items:["Open Renee's post in Immersive Reader.","Close Immersive Reader and change the theme to Light.","Join the Front Office Huddle and turn on live captions.","Raise your hand using the keyboard shortcut or the Raise button.","In a Word document or on paper, name two accessibility tools in Teams and one coworker situation where each would help."]},{type:"callout",variant:"success",text:"Deliverable: Submit your Challenge Lab results page (print it or save it as a PDF) and your two examples to your instructor or course folder."}]}],level:"Intermediate",estimatedMinutes:60}]}};